quests[9402] = { id = 9402, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fetch!", description = "So... {name} is it?  Don't be flattered I know your name, one of my students has been fawning over you and won't shut up.\n\nHmm... if you'd like to impress <her/him>, why don't you do something for me?  There's an azure phial at the bottom of the pond behind me.  Dive in, retrieve it, and bring it here.", progress = "How's the water?", completion = "Oh, well done...  I told you to jump in a pond, and you did.  I can only imagine what you'd do if one of your good friends asked it of you.\n\nIf you want a reward for your efforts, it is this: never lift a finger without first knowing what's in it for you.  The {class}'s mind is his greatest weapon.  Remember that and try to use yours a bit more.", objectives = "Dive to the bottom of Stillwhisper Pond and retrieve the Azure Phial for Instructor Antheol.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9403] = { id = 9403, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Purest Water", description = "Now that you've learned a little lesson, I'll offer you something more substantial.  It concerns your ability to defend yourself in close combat.  Of course, you should only resort to melee in the most dire of circumstances, but that is no excuse to be unprepared.\n\nI can assist you in creating a staff befitting a mage of your learning.  Simply take the phial you retrieved for me and fill it at the base of Elrendar Falls.  Just follow the river southeast from here.", progress = "Only water from the Elrendar Falls has the purity required for use with magic.  Do you have it?", completion = "Let's see what you've brought me...\n\n<He holds the phial up to the light and examines it closely.>\n\nYes, this will do.  Well done, {name}.", objectives = "Instructor Antheol wants you to fill the Azure Phial at Elrendar Falls.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9404] = { id = 9404, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Recently Living", description = "You may have noticed the walking trees near Elrendar Falls.  As the keepers of nature, they are infused with a primal magic we can reform to our own purposes using the pure water you have already brought to me.\n\nUnfortunately, the green keepers are gnarled and twisted creatures, so you may need to kill a few before you find a useable branch.", progress = "Do you have the living branch?  Hand it over quickly!", completion = "You've done as I've asked, {name}, and you may take your reward now.", objectives = "Slay the Eversong Green Keepers until they yield a Living Branch for Instructor Antheol.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9405] = { id = 9405, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Warchief's Mandate", description = "As you know, the warchief put his power behind this expedition for one reason.  This is the world we came from.  This is where our roots lie.\n\nThis journey means different things to orcs and blood elves.  To them it's a search for the promised land.  To us it's more like returning home.\n\nWhoever made this axe is familiar with the old ways and we must contact them.  This is too important for us to use ordinary tracking methods.  Show the weapon to Far Seer Regulkut; she will know what to do.", progress = "Tell me what you seek, so that I may help you find it.", completion = "I understand Nazgrel's request, {class}.  Say no more.", objectives = "Bring the Heavy Stone Axe to Far Seer Regulkut at Thrallmar in Hellfire Peninsula.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9406] = { id = 9406, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Mag'har", description = "This news you bring from beyond the Dark Portal...  you want us to believe the son of Durotan ruled over the lands beyond it... free from any demonic taint?  And that now his people have returned to this world?\n\nI hope for your sake that this isn't some manner of joke, {class}.  What this means to my people... cannot be described.  I must send word to Nagrand at once!  Hellscream must hear about this.\n\nTake this letter back to your leader in Thrallmar.  Tell him the Mag'har welcome them!", progress = "What do you bring us, {name}?", completion = "You're certain of this?  This is big news, {name}.  These orcs can surely help our cause both here and at home!", objectives = "Deliver the Letter from the Mag'har to Nazgrel at Thrallmar in Hellfire Peninsula.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9407] = { id = 9407, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Burning Crusade: Through the Dark Portal", description = "For years the Dark Portal loomed silent... forgotten.  But it is silent no longer.\n\nAfter stopping the demonic assault here, our forces breached the portal and met the demons on their own ground!\n\nNow, we are locked in a savage war, and there are some who think we might not win.  So it is our duty, our grim pleasure, to battle the fiends of Outland and ensure our victory, {name}.\n\nIf you would help us, then report to Lieutenant General Orion at once. He awaits you in the Outland...", completion = "Our Expedition made it safely through the Portal and set up a new base called Thrallmar. Yet as you can see, the Burning Legion moved in and cut us off from our brothers. Clearly, the demons hope to retake the Dark Portal and prevent us from gathering reinforcements from Azeroth.", objectives = "Travel through the Dark Portal and find Lieutenant General Orion. He awaits your arrival on the other side, in Outland.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9408] = { id = 9408, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forgotten Heroes", description = "While it pains me to know that we have lost so many soldiers in our efforts to breach the portal, my heart swells with pride to know that the original expeditionary force is still alive.\n\nI can hardly believe it; but here they stand - a testament to the resolve of the Alliance.\n\nInside that keep stands one of our greatest heroes: Danath Trollbane! Seek him out, {class}. He has already met and addressed all of our soldiers. He will surely want to meet you.", sourceObjective = "Speak with Force Commander Danath Trollbane at Honor Hold.", sourceObjectiveStatus = "unverified-source-field" }
quests[9409] = { id = 9409, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Urgent Delivery!", description = "Now that you've gathered all that we need to replenish our healing crystals, I need you to deliver the vials to Zalduun, our priest.  You'll find him tending to our wounded inside the central chamber of the ship.", progress = "Hello, {class}.  What have you there? Is it for me?", completion = "Good work!  This will do nicely to replenish our depleted healing crystals.\n\nBut now that you're here, I think I have another use for you, if you're willing?", objectives = "Deliver the Bundle of Vials to Zalduun at the Crash Site in Ammen Vale.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9410] = { id = 9410, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Spirit Guide", description = "Even our best tracking wolves' senses can fail them, {name}.  The spirits have a way of seeing the world differently than ours.  The being you will call forth will find the person you seek, for they'll be drawn not to their scent but their essence.\n\nGo now, {class}, take this totem with you and use it at the location you found the stone axe.", progress = "You are lucky to be alive.", completion = "Who are you to walk in here unannounced?  I ordered my men to stay their hand only because Ryga sensed that the spirits were with you.  \n\nSpeak freely, but choose your words wisely.  We rarely trust strangers this close to the Citadel.", objectives = "Use the Wolf Totem at the location where you found Krun Spinebreaker's body and follow the Ancestral Spirit Wolf.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9415] = { id = 9415, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Report to Marshal Bluewall", description = "Are you Marshal Bluewall's new recruits? Of course you are.\n\nWhat are you waiting for? Good soldiers are dying in the desert. Aren't you excited to join them?\n\nNow, get going and don't dry out on the way.", completion = "The Alliance needs every able body they can get. The Horde has been receiving a steady supply of reinforcements from the northern part of the continent, and it's been a struggle to keep up.\n\nLet me explain the situation to you.", objectives = "Speak with Marshal Bluewall at the Alliance encampment near Hive'Zora.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9416] = { id = 9416, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Report to General Kirika", description = "You must be one of General Kirika's new recruits. It's about time you showed up. Bodies wear down quick in the desert.\n\nThe dwarves have been getting reinforcements daily, and we can't afford to lose ground in our struggle for resources in Silithus.\n\nGet your instructions from the General. It's not my job to train you, just find you.", completion = "It's good that you're here, but there's no time to waste making small talk. You need instructions, and then you need to get out there.\n\nListen up.", objectives = "Speak with General Kirika at the Horde encampment near Hive'Regal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9417] = { id = 9417, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Arakkoa Threat", description = "The arakkoa are smart creatures... smart as any gnome you ever met.  They have this way with magic and a violent temper, however. \n\nLately they've taken to attacking Honor Hold patrols, which is why we were sent here.  See, Mirren and I are world-famous marksmen, we are!  But fowl and game are what we specialize in... not these... lightning-invoking birdmen.\n\nSo what do you say you give us a hand in this one assignment?  You'll find the Den of Haal'esh to the southeast.", completion = "Great job, {name}!  I hereby proclaim you an honorary Longbeard.\n\nStick around and have a drink with us, won't you?", objectives = "Gremni Longbeard in Hellfire Peninsula wants you to slay 4 Haal'eshi Windwalkers and 6 Haal'eshi Talonguards.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9418] = { id = 9418, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Avruu's Orb", description = "<As you hold the orb closer to you, you hear a voice address you.>\n\nI sense you're not of the arakkoa, so I will attempt to barter for my freedom.  My name is Aeranas. I once ruled over the eastern winds.  The Haal'eshi mage, Avruu, trapped me inside this orb.\n\nFind the altar the arakkoa used to enslave me.  It is hidden to the southeast of the arakkoa's den.  Approach it with the orb and give it to me once I'm free.  In exchange for my liberty I'll reward you with powerful treasure!", progress = "The freedom I've yearned for is finally mine!", completion = "With this orb I regain my liberty.  Take your reward, mortal, so that our debt may be settled.", objectives = "Take Avruu's Orb to the Haal'eshi Altar southeast of the Den of Haal'esh in Hellfire Peninsula and give it to Aeranas once he's free.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9419] = { id = 9419, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scouring the Desert", description = "We recently found out that the Horde has been scavenging the Silithus desert for resources, but paid them little mind. We thought it could not be worth it to station large numbers in this sweltering desert.\n\nHowever, it was discovered the importance of the resources, and now we are scrambling to catch up.\n\nIf I have your assistance, you must go into the desert and recover the silithyst and return it here.", completion = "Thank the Light you were successful.\n\nNow if we could only have started this sooner, our need would not be so desperate. We must keep the bounty of the desert from falling into the hands of the Horde.", objectives = "Find and deliver Silithyst to the Silithyst Extractor, then speak with Marshal Bluewall at the Alliance encampment near Hive'Zora.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9420] = { id = 9420, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Finest Down", description = "The arakkoa at the Den of Haal'esh, south of here, breed a magnificent species of birds called kaliri.  Their feathers would fetch a bundle at the trading posts back in Azeroth.  Just think of all the ale I could buy then!\n\nTell you what, you bring me a stack of kaliri feathers and I'll give you my very own hat.  What do you say?  You'll never find a hat like this one!  Do we have a deal?", progress = "Did you bring me the kaliri feathers, {class}?", completion = "You did your part.  I guess a deal is a deal!\n\nHere you go, friend.  Treat it well.", objectives = "Mirren Longbeard in Hellfire Peninsula wants you to bring him 8 Kaliri Feathers from the various kaliri found in the Den of Haal'esh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9421] = { id = 9421, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shaman Training", objectives = "I am Firmanvaar and you are wise to seek me out.  It is my calling to provide instruction to {class}, especially those who are just beginning to learn.\n\nShamanism is only now being relearned amongst the {race}, {name}.  You are brave to follow its path as it is not popular amongst your kind.\n\nI will be here when you feel you are ready for further training.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9422] = { id = 9422, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scouring the Desert", description = "For some time now, we have been tapping the crystal resources of the Silithus desert. The only dangers we faced were from the creatures that made this place their home and the oppressive sand and dust and heat.\n\nBut now the Alliance seems to have caught on to what we have found here. It is now a race between us to capture the natural resources, and keep them from the other.\n\nI need every set of hands that is available. I hope I have yours.", completion = "You've done well, {name}. These resources will be added to our stockpiles, and every bit is to our gain and our enemy's loss.", objectives = "Find and deliver Silithyst to the Silithyst Extractor then speak with General Kirika at the Horde encampment near Hive'Regal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9423] = { id = 9423, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Obadei", description = "With Sedai's death confirmed, you're left with the unpleasant task of returning to Obadei with the grim news.", completion = "Sedai, dear brother...\n\nThose cowardly orcs!  He was unarmed, how could they?\n\nLeave me be, {name}.  I thank you for your assistance but I wish to be alone with my thoughts now.", objectives = "Return to Anchorite Obadei at the Temple of Telhamat in Hellfire Peninsula and inform him of Sedai's death.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9424] = { id = 9424, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Makuru's Vengeance", description = "Sedai was like a brother to Makuru.   We owe him our lives and more!  They call Makuru crazy but if the Omenai are not going to do anything about his death then they're the crazy ones!\n\nMakuru doesn't have much to call his own in this world, but he will give you his only possession if you avenge Sedai.  \n\nI've seen the brown orc Mag'har grunts before, up in the hills to the northeast.  They hate us!  They don't deserve our mercy!  Go, avenge Sedai!  Bring me their ancestral beads as proof!", progress = "Did you avenge Sedai for Makuru?", completion = "Yes... revenge!  You did good.\n\nYou take this now.  It was a gift from Sedai.  It only makes Makuru sad to see it.", objectives = "Makuru at the Temple of Telhamat in Hellfire Peninsula wants you to bring him 10 Mag'har Ancestral Beads.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9425] = { id = 9425, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Report to Tarren Mill", description = "Ah, good to see you here, {class}!  I've a task that you are perfectly suited to.\n\nAs new members of the Horde, we need to make sure that we support their efforts and help them with their problems.  That way they'll be more receptive to helping us with ours.\n\nTravel to the Forsaken town, Tarren Mill, in the Hillsbrad Foothills to the southeast.  Check in with Advisor Duskingdawn when you arrive.", completion = "My, my!  Another of my brothers arrives to pitch in.  Good!  There is much to be done in support of our new Forsaken friends, {class}.  Ask around to see who you can help out.\n\nI know that you will support them to your utmost ability!", objectives = "Travel to Tarren Mill in the Hillsbrad Foothills and speak with Advisor Duskingdawn.Ah, good to see you here, {class}!  I've a task that you are perfectly suited to.\n\nAs new members of the Horde, we need to make sure that we support their efforts and help them with their problems. That way they'll be more receptive to helping us with ours.\n\nTravel to the Forsaken town, Tarren Mill, in the Hillsbrad Foothills to the southeast. Check in with Advisor Duskingdawn when you arrive.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9426] = { id = 9426, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Pools of Aggonar", description = "Much has changed since the days when we called this land Draenor.  Parts of the land have been forever changed by the demons' taint.\n\nOne such place is known as the Pools of Aggonar.  It was once the location of our people's sacred springs.  The blood of the demon Aggonar fouled the very essence of the holy waters.  This fel blood has spawned foul beings that must be cleansed if we're ever to reclaim the pools.  Travel east of here and slay the Terrorfiends and slimes that wander the pools.", completion = "Yes, I feel the fel presence in the pools weakening.\n\nYou've done well, {name}.", objectives = "Amaan the Wise wants you to go to the Pools of Aggonar and slay 6 Terrorfiends and 6 Blistering Rots.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9427] = { id = 9427, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cleansing the Waters", description = "I must ask that you finish what we've set in motion.  Now that the demonic influence has weakened you must take this cleansing vial and pour it at the very source of the taint - Aggonar's own corpse.\n\nYou will find the demon's bones at the northern end of the pools.  Beware, I sense that Aggonar's essence has not quite left this world.", progress = "You return, {name}.  Are the waters cleansed?", completion = "The essence of Aggonar lived on in the form of his foul offspring Aggonis.  With your success in defeating the demon, we can begin to work towards restoring the pools to their former purity.\n\nYou have our thanks, {name}.  Your work will have a deep impact in this world.", objectives = "Amaan the Wise wants you to travel to the Pools of Aggonar and use the Cleansing Vial at Aggonar's corpse. Return to him when Aggonar's essence is cleansed from the water.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9428] = { id = 9428, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Report to Splintertree Post", description = "<The ambassador keeps her voice low as she leans in close.>\n\nYour reputation precedes you, {name}.  I want you to travel to Splintertree Post in Ashenvale.  The easiest way to get there on foot is to travel west through Durotar and the Barrens, and then turn north at the fork in the road.\n\nWhen you arrive, speak with Advisor Sunsworn.  Travel carefully; Ashenvale can be a very dangerous place!", completion = "The ambassador sent word ahead, so I've been expecting you.\n\nThe ambassador simply wants you to do as much as you can to help out around here.  She said something about making sure to cement our relationship with the rest of the Horde.\n\nAsk around - there are others in need of help further back in the Post.  And I hear that there's another Horde outpost called Zoram'gar Outpost on the coast all the way to the west.", objectives = "Travel to Splintertree Post in Ashenvale and speak with Advisor Sunsworn.<The ambassador keeps her voice low as she leans in close.>\n\nYour reputation precedes you, {name}. I want you to travel to Splintertree Post in Ashenvale. The easiest way to get there on foot is to travel west through Durotar and the Barrens, and then turn north at the fork in the road.\n\nWhen you arrive, speak with Advisor Sunsworn. Travel carefully; Ashenvale can be a very dangerous place!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9429] = { id = 9429, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Travel to Darkshire", description = "I am told that there is a thorn in the side of the kingdom of Stormwind.  It is known as Duskwood, and it is a place that is filled with evil and the vile stench of undeath.\n\nAs we're trying to help as much as we can, I would like for you to travel southeast to the main human settlement there, named Darkshire.  Anchorite Delan will be awaiting your arrival.", completion = "Greetings, {class}.  I trust that your journey here was uneventful?\n\nThese poor souls are beset upon all sides by the creatures of the night.  It is our wish that you lend them what aid you can in pushing back the darkness.\n\nTravel about the town and get to know its inhabitants.  Please, {name}, help them in any way that you can.", objectives = "Travel to Darkshire in Duskwood and speak with Anchorite Delan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9430] = { id = 9430, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sha'naar Relics", description = "As I've told you before, I do not require eyes to see what others cannot.  I will not pass judgment on what you did on Makuru's behalf, yet I think you need to see beyond what your eyes show you.\n\nTravel southwest to the Ruins of Sha'naar and salvage any relics you find.  If fate wills it you will find what we need.\n\nThe meaning of my request might not be immediately apparent.  Have faith though, {name}.  Clarity comes to those with patience.", progress = "Did you retrieve the Sha'naar relics, {name}?", completion = "You're very fortunate.  Just as I had hoped, you've found a special relic among these other ones.", objectives = "Amaan the Wise at the Temple of Telhamat in Hellfire Peninsula wants you to travel to the Ruins of Sha'naar and retrieve 10 Sha'naar Relics.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9431] = { id = 9431, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Different Approach", description = "What's a sin'dorei doing standing on the top of a windswept butte in Thousand Needles instead of the halls of Silvermoon?\n\nIt's simple. My brethren will no longer have me. Every copy of my treatise on natural cures for our magical addiction was burned.\n\nI can safely pursue my research here, but I am without my reagents. If you'd be willing to gather purifying earth from the thundering boulderkin near the western end of the Needles and deliver it to my associate at Whitereach Post, I'd appreciate it.", progress = "Magistrix Elosai's note was a bit cryptic, but I think I understand what she wants me to do. If you have the earth she talked about, I can put it into the vessel you'll need for the moonwell water.", completion = "What? She didn't mention the moonwell? That's what she had in mind all along. I admit the whole thing's a bit wacky, but who am I to turn away a client, especially when she's the only one I've got?\n\nMaybe trying to sneak into a night elf settlement and steal water from their moonwell isn't the most prudent thing I've ever helped a customer do, but her money is as gold as anyone else's!", objectives = "Gather 2 handfuls of Purifying Earth from Thundering Boulderkin and take them to Wizlo Bearingshiner at Whitereach Post.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9432] = { id = 9432, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Travel to Astranaar", description = "I am glad that you are here to help.  In fact, there is something that you can do.\n\nAs part of our inclusion within the Alliance, I would like for you to travel to the night elf town, Astranaar.  It is located in Ashenvale, a large forest that is south of Darkshore on the continent of Kalimdor.\n\nPlease speak with Vindicator Palais when you arrive to see if there's anything that you can do to help the inhabitants.", completion = "Always good to see a semi-familiar face.  You must be {name}.  Emissary Valustraa sent me word to expect you.\n\nThe people of Ashenvale need our assistance, {class}.  Speak with the citizens of Astranaar to see how you can help.", objectives = "Travel to Astranaar in Ashenvale and speak with Vindicator Palais.I am glad that you are here to help. In fact, there is something that you can do.\n\nAs part of our inclusion within the Alliance, I would like for you to travel to the night elf town, Astranaar. It is located in Ashenvale, a large forest that is south of Darkshore on the continent of Kalimdor.\n\nPlease speak with Vindicator Palais when you arrive to see if there's anything that you can do to help the inhabitants.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9433] = { id = 9433, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Dip in the Moonwell", description = "Stop looking at me like that! I didn't say I was going to send you to Thalanaar's moonwell out in the open with dipper and a flask!\n\nI've been, err... tinkering with a product I was transporting for a client. In fact, I've already set up a portable control console for the Robotron out near Thalanaar. You'll need to bring this control unit with you and use it in the vicinity of my concealed console.\n\nIf my client ever heard that I so much as removed Robotron from its packaging, he'd hang me by my ears!", progress = "Did it do the job?", completion = "That worked better than I expected! Chalk up another one for good old goblin ingenuity!\n\nThe only problem is that it's hopelessly covered in dust! It's going to take me forever to get this thing cleaned up and replaced in its crate.\n\nOf course, time is the one thing I have in ample supply.", objectives = "Use the Robotron Control while standing near the Concealed Command Console hidden in a small cluster of bushes on the rim of the needle closest to Thalanaar to take command of a Robotron 3000. Pilot the robot to the western edge of Thousand Needles where the Alliance outpost of Thalanaar is located. Use the robot to collect a sample of the moonwell's water and return it to Wizlo Bearingshiner at Whitereach Post.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9434] = { id = 9434, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Testing the Tonic", description = "<Wizlo retrieves the water sample from the robot and places it in a crate with the boulderkin earth and several other items.>\n\nThere you go, that's everything on Magistrix Elosai's list. Tell her that it's been a pleasure working with her and that I wish her luck in her research.", progress = "Were you and Wizlo able to gather the reagents?", completion = "Excellent, it appears everything is here. Now, all I have to do is mix everything together and give it a try. If this tonic does what my research indicates it should do, I may have discovered a way to lessen the effects of my people's magic addiction.\n\nYou're about to witness history in the making, {name}. Just think, without your help, this wouldn't have been possible.", objectives = "Deliver the Crate of Reagents to Magistrix Elosai at Freewind Post.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9435] = { id = 9435, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Missing Crystals", description = "If there's one great truth about Hillsbrad, it's that this region is destined to live under the shadow of war. Even something as innocuous as a cartload of stone is a target.\n\nNormally the loss of building materials is no great setback, but the most recent shipment from the Azurelode mine contained a crate of rare crystals I was eager to study. Forsaken raiders intercepted the cart and drove it northeast to a tower they're attempting to rebuild. It's imperative that we retrieve those crystals, {class}!", progress = "Were you able to retrieve the crystals from the Forsaken?", completion = "Thank the Light! From the tone of the foreman's letter, it sounded as if that box of crystals contained the only known samples from the mine. If we had lost them, {name}, we may never have seen another like them.\n\nI can't thank you enough for your help.", objectives = "Retrieve the Shipment of Rare Crystals from the Forsaken and return it to Huraan in Southshore.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9436] = { id = 9436, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bloodscalp Insight", description = "Well met, {class}. I've made a habit of studying the fighting techniques of the various troll tribes in my travels, and I've noticed a trend. The Bloodscalp trolls at the Tkashi Ruins and Bal'lal Ruins to the north use some of the same tactics as the Amani of the northern forests.\n\nTheir magic seems to have diverged in an interesting direction and they've used it to become the strongest tribe in the area. It could form the core of a powerful weapon against the Amani, but first I must find out more about it.", progress = "Do not fail me, {name}. If we can bend this Bloodscalp magic to our will, my people may yet eliminate the Amani threat.", completion = "Well done. Now, this is curious...\n\nThe inscription on this totem is in a language no troll could ever hope to learn, but one that is known to us. It names the bearer as an ally of a water elemental named Naias and marks him as one worthy to channel his power.\n\nThis is most unexpected, but not entirely bad, {name}. With your help, I'd like to pursue this further.", objectives = "Nemeth Hawkeye at Grom'gol Base Camp wants you to bring him a Bloodscalp Totem from a Bloodscalp Shaman.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9437] = { id = 9437, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Twilight of the Dawn Runner", description = "The ogres here are useful for little more than crude jokes, sour ale, and bouts of headbutting. When my ship, the Dawn Runner, ran aground, those curs from Theramore made off with my cargo and last surviving crewman. I made my way here searching for help, but those good-for-nothing ogres stared blankly at me when I told them my story.\n\nI could use the help of a reliable {race} in recovering what remains of my cargo and freeing Ithania from North Point Tower, to the northeast, where they're being held.", progress = "Have you freed Ithania and reclaimed my cargo from those glorified privateers?", completion = "Well done, {name}! As soon as Ithania has had time to rest and my preparations are complete, we'll depart this sodden wasteland and head back to civilization.", objectives = "Balandar Brightstar in Brackenwall Village wants you to reclaim the Dawn Runner Cargo and rescue his first mate Ithania from forces of Theramore at North Point Tower.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9438] = { id = 9438, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Messenger to Thrall", description = "The warchief has been waiting for word of this ever since we set foot on Outland.  Now you get the honor of giving him the news of the Mag'har yourself.\n\nGo quickly, {name}.  Take this letter with you; it bears my personal seal.  There is nothing that Thrall wants to hear more than the message you bear.", objectives = "Travel to Orgrimmar and give Thrall the Letter from Nazgrel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9439] = { id = 9439, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unclaimed Baggage", description = "This is Kargath? Oh, dear. I expected a, a... well, some kind of settlement, some sign of civilization here in the wilderness.\n\nThere must be a mistake; surely this hovel full of uncouth, unwashed, sniggering savages can't be the headquarters of the Expeditionary Force. The loutish barbarians had the gall to laugh at me when I told them about how the Dark Iron dwarves robbed me and then disappeared into the Angor Fortress. I can count on you to help me recover my possessions and my dignity, can't I?", progress = "For Sunstrider's sake, don't stare at me! It's bad enough I'm forced to endure out here in my soiled clothing! After all I've been through, the last thing I need is to be gawked at. Did you manage to collect my possessions from that hole-in-the-ground those Dark Irons call a fortress?", completion = "You're a miracle worker, {name}! I tell you, I've never been so eager for a change of clothes in my life.\n\nAnd my rapier! I felt positively naked without my blade.\n\nYou are to be commended and rewarded for your efforts. Never let it be said that Sarophas failed to acknowledge the little people who've helped him along the way!", objectives = "Retrieve the Advisor's Pack and Advisor's Rapier from their holding places in the Angor Fortress and return them to Advisor Sarophas at Kargath.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9440] = { id = 9440, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "ittle Morsels", description = "I'm perfecting a weapon to use against the draenei and you're going to help me!\n\nThe Lost Ones are the backward cousins of the draenei, and I've been experimenting on them.  I just need you to feed some fel-tainted morsels to their captured livestock.  In turn, when they slaughter and eat the animals, they'll be cursed!  That'll show that stuffy Anchorite Avuun at the Harborage!\n\nGo now, hurry!  You'll find the Lost Ones and their caged animals to the northeast at the Fallow Sanctuary.", progress = "Did you feed their captured animals all of the morsels?  Wait!  You didn't give any to that stupid human they have out there in the cage, did you?\n\nOh, good!  That would have been a waste!", completion = "Oh, excellent! I can't wait to measure the effects from this latest batch!\n\nWell, you did an admirable job, sweetie.  Wish I could give you more than this for the entertainment you've provided, but you know how it is.  There's not much money to be made out here in the swamp.\n\nI'm sure it was worth it just for the fun!", objectives = "Feed the Fel-Tainted Morsels to the Lost Ones' captured animals. Then return the leftovers to Cersei Dusksinger at Stonard in the Swamp of Sorrows.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9441] = { id = 9441, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Envoy to the Mag'har", description = "I'd leave for Outland this very minute after hearing the news you brought.  Important matters require my attention in Durotar, however.\n\nI will arrange for a fitting tribute to be sent to the Mag'har immediately.  I will send my most trusted diplomats as well.  This will all take time... I need someone to represent us there right now.\n\nI must place my trust on you, {name}.  Go to the Mag'har Post in Hellfire and render whatever services you can to my kin.  Do not fail me, {name}.  Too much depends on this.", sourceObjective = "Thrall wants you to return to Gorkan Bloodfist at Mag'har Post in Hellfire Peninsula and offer him your services.I'd leave for Outland this very minute after hearing the news you brought. Important matters require my attention in Durotar, however.\n\nI will arrange for a fitting tribute to be sent to the Mag'har immediately. I will send my most trusted diplomats as well. This will all take time... I need someone to represent us there right now.\n\nI must place my trust on you, {name}. Go to the Mag'har Post in Hellfire and render whatever services you can to my kin. Do not fail me, {name}. Too much depends on this.", sourceObjectiveStatus = "unverified-source-field" }
quests[9442] = { id = 9442, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Debilitating Sickness", description = "It is good that you've offered to aid us, {name}.  Our grunts have fallen sick from drinking contaminated water and I'm missing an ingredient to produce a healing salve.  I'm in need of a rare mushroom called drycap.\n\nOur foremost orders are to keep our location secret and not risk being spotted while looking for it, or I would go myself.  The only place in Hellfire Peninsula where drycap grows is a cave at the Great Fissure, south of here.\n\nBe extremely careful if you choose to seek it.", progress = "Did you obtain the mushroom I need, {name}?", completion = "Gorkan said good things about you.  They're all turning out to be true.\n\nThanks for your help.", objectives = "Earthcaller Ryga at Mag'har Post in Hellfire Peninsula wants you to bring her 1 Drycap Mushroom from a cave inside the Great Fissure.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9443] = { id = 9443, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The So-Called Mark of the Lightbringer", description = "I was once a pupil of Uther Lightbringer, founder of the Knights of the Silver Hand. I saw how he mishandled Prince Arthas's training. It led to the destruction of my homeland, Quel'Thalas, and I blame Uther and his incompetence for all of it! And now he has a tomb in his honor - how lovely.\n\nMy sources tell me that the scarlet fools are keeping one of his 'holy' relics atop their guard tower near the gates of Hearthglen.\n\nGo to the Western Plaguelands and retrieve it for me.", progress = "When you've managed to retrieve his 'mark', we're going to change it a bit; make it better.", completion = "The first step is complete. Hand me the Mark of the Lightbringer and I will transform it into something more suitable.\n\nThen my revenge will begin in earnest, {class}!", objectives = "Obtain the Mark of the Lightbringer and return it to Mehlar Dawnblade at the Bulwark in the Western Plaguelands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9444] = { id = 9444, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Defiling Uther's Tomb", description = "There, that's better.  I've added a little fel magic to it.\n\nNow, you must take it to his resting place in the Western Plaguelands.  Use the corrupted holy symbol in the presence of Uther's statue to defile his tomb!  You'll have to get close for it to work.\n\nTo find the tomb go southeast of the Ruins of Andorhal.  Return to me when the deed is done.\n\nBe quick about it, {class}!", progress = "It is done, then?  Uther's Tomb is defiled?", completion = "Forgives me?  He FORGIVES ME?!!!\n\nI don't care what that old ghost had to say - it was his fault!  Everything that's happened to Quel'Thalas was a result of his incompetence!\n\nIt is clear that the defiling did not work.  Go, be gone from my sight!  I must think this through.", objectives = "Defile Uther's Tomb and return to Mehlar Dawnblade at the Bulwark in the Western Plaguelands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9446] = { id = 9446, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tomb of the Lightbringer", description = "Now that you've recovered the Mark of the Lightbringer, all that is left is to return it to Uther's Tomb.\n\nWould you be willing to accompany me there to do this?  It's not far and I would enjoy your company.  Afterward you can come back here and relate the experience to High Priestess MacDonnell.\n\nWhat say you, {name}?", completion = "The Lightbringer appeared before you?  That is amazing!  And you made it all possible through your selfless help to the anchorite.\n\nIf even half of the stories are to be believed, Uther was a great man.  And, like him, you are a true hero to all of the good people of Azeroth, {name}!", objectives = "Escort Anchorite Truuen to Uther's Tomb in the Western Plaguelands. Afterward, speak with High Priestess MacDonnell at Chillwind Camp in the Western Plaguelands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9447] = { id = 9447, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Administering the Salve", description = "I've prepared a simple salve that should restore our grunts' strength with the herbs you brought me.  Take it and administer it to any debilitated grunts you see in the vicinity.  Return to me when you're done.", progress = "You've returned, {name}.  Is your task complete?", completion = "May the spirits bless you, {name}.  The Mag'har are in your debt.", objectives = "Earthcaller Ryga wants you to administer the Healing Salve to 10 Debilitated Mag'har Grunts nearby Mag'har Post in Hellfire Peninsula.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9448] = { id = 9448, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "ercy for the Cursed", description = "That blood elf witch, Cersei Dusksinger, has been cursing the Lost Ones, I just know it!  I don't know why or how, but the results are tragic.  Several of the Lost Ones have now been further corrupted - cursed with even more fel energies!\n\n{class}, can you find it in you to take pity on these poor creatures?  They should not have to live out the rest of their lives in such a horrible condition.\n\nYou'll find these cursed Lost Ones at the Fallow Sanctuary, east down the path.", completion = "It is done then.  I thank you for showing your compassion.  Once corrupted by whatever Cersei was feeding them, there is nothing else that could be done.\n\nThey are now at peace and hopefully my studies of the others will bear fruit so that they can be rehabilitated.", objectives = "Slay 3 Cursed Lost Ones and then return to Anchorite Avuun at the Harborage in the Swamp of Sorrows.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9449] = { id = 9449, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call of Earth", description = "The time has come, {name}.  You have grown to the point where you are ready to commune directly with the elemental spirits of this world.\n\nBut be warned.  I can sense that the manner of our entry into this world, and its unfortunate side effects, have angered the earth spirits and caused an imbalance of the elements.\n\nIf you are to create your earth totem, you must first speak with the Spirit of the Vale.  You will find it in the Sacred Grove, nestled in the hills to the northwest.", sourceObjective = "Speak with the Spirit of the Vale at the Sacred Grove in Ammen Vale.The time has come, {name}. You have grown to the point where you are ready to commune directly with the elemental spirits of this world.\n\nBut be warned. I can sense that the manner of our entry into this world, and its unfortunate side effects, have angered the earth spirits and caused an imbalance of the elements.\n\nIf you are to create your earth totem, you must first speak with the Spirit of the Vale. You will find it in the Sacred Grove, nestled in the hills to the northwest.", sourceObjectiveStatus = "unverified-source-field" }
quests[9450] = { id = 9450, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call of Earth", description = "The balance of the elements has been disrupted by the violent intrusion of the draenei to the Vale.  Your crash has caused the spirits of earth to be enraged and turn upon the other elements who have come to quell them.  You will learn that an understanding of the elements can only come when all are in harmony.\n\nThus, it falls to you to seek a balance.  Behind me in the grove you will find the restless spirits of earth warring upon the other three elements.  Help restore the balance.", objectives = "Slay 4 Restless Elements of Earth and then return to the Spirit of the Vale at the Sacred Grove in Ammen Vale.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9451] = { id = 9451, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call of Earth", description = "I will now give you a piece of my physical being that you may create your earth totem.  Return it to he who sent you here.\n\nYou and I will be bound together for all time.  Throughout your life the forces of earth will be at your disposal.  The balance will come when your bones return to us at the end of your days.\n\nUse our power wisely.", objectives = "Deliver the Earth Crystal to Firmanvaar at the Crash Site in Ammen Vale.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9452] = { id = 9452, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Red Snapper - Very Tasty!", description = "I've found that these waters are bustling with red snapper, a very tasty fish. With a fishing net, I can catch enough to feed dozens of draenei! Unfortunately, I was recently attacked by a creature known as a murloc while netting in the river and have suffered some injuries that prevent me from doing my job. I need help!\n\nUse this fishing net near schools of red snapper, found in the Crystalbrook river to the east, to catch the fish.\n\nWhat do you say? Remember to return the net when you are finished.", progress = "Watch out for murlocs: Strange and extremely annoying little creatures.", completion = "I hope the murlocs didn't cause too much trouble, {name}. I owe you a great debt of gratitude for all that you've done.\n\nPerhaps I could teach you how to fish? I'll even supply the fishing pole and a bauble.", objectives = "Use the Draenei Fishing Net to catch 10 Red Snappers. Return both the fish and the net to Diktynna on Azuremyst Isle when the task is complete.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9453] = { id = 9453, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Find Acteon!", description = "You did a wonderful job, {name}. Our people will be thankful for this bounty. With that said, would you mind taking this haul of red snapper to Acteon at Azure Watch?\n\nHe shouldn't be hard to find as he is awaiting this catch.", progress = "What do you think of my armor? Crafted it myself! It's a little different than what we'd traditionally wear but extremely comfortable.", completion = "Poor Diktynna... That murloc gave her quite a scare.\n\n<Acteon sighs.>\n\nHopefully she will recover from the injuries soon...\n\nSo I presume you're looking for work. Well there's plenty of that to be found at Azure Watch!", objectives = "Deliver the Crate of Red Snapper to Acteon at Azure Watch.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9454] = { id = 9454, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Great Moongraze Hunt", description = "You're starting to make a name for yourself, {name}. How about trying your hand at hunting?\n\nBack on Draenor, our greatest hunters would hunt a beast that resembled the moongraze stag of this region known as a talbuk.\n\nIf you think yourself draenei enough, go out into the wilds and kill enough stags to fill your pack with meat.\n\nYou will find them grazing south of Azure Watch. Watch out for their horns!", progress = "The stag hides are frail which tend to make for tender, succulent flesh.", completion = "Well done, {name}, well done!\n\nHere, I cooked up some tenderloins while you were gone. Maybe you'd like the recipe, too?", objectives = "Bring 6 Moongraze Stag Tenderloins to Acteon at Azure Watch.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9455] = { id = 9455, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Strange Findings", description = "The crystal you found on the nightstalker runt's body appears to be a piece of the Exodar. This may help explain the unusual appearance and demeanor of some of the animals in this region.\n\nTake the crystal back to Azure Watch. The exarch will surely want to know about this discovery.", progress = "You found what? Where?", completion = "How did such a thing end up in the stomach of a nightstalker? Could the debris from the crash have contaminated more beasts?", objectives = "Deliver the Faintly Glowing Crystal to Exarch Menelaous at Azure Watch.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9456] = { id = 9456, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nightstalker Clean Up, Isle 2...", description = "I'm not going to make any excuses for what you've found. This is clearly our fault. We had gotten reports of crushed crystal fragments showing up in the river to the east but chose to ignore the implications. Now we can either sit around on this island and cry about the tragedy that has befallen this land or we can do something about it and prevent it from spreading.\n\nIf you've got the stomach for it, I want you to go back into the wilds and kill as many of the infected nightstalkers as you can find.", progress = "We can't risk this contamination spreading. The reports I've heard come from Blood Watch are bad enough. This has to be stopped now!", completion = "I just hope it's not too late...", objectives = "Exarch Menelaous at Azure Watch has asked that you slay 8 Infected Nightstalker Runts.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9457] = { id = 9457, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Unusual Patron", description = "So this Naias is the mastermind behind the Bloodscalp and their exotic magic? I'll admit, this is the last place I expected my inquiry to lead, but no matter, our findings may still prove useful.\n\nOff the coast to the northwest is an island inhabited by lesser water elementals. There's a crude stone slab there that might serve as an altar for the likes of the trolls. Take the totem you found to that altar. Let's see if we can draw this Naias out and distill his power into a more agreeable form.", progress = "What news of Naias, {name}?", completion = "I can feel the raw power contained in this gem, {name}. I'll send it to Silvermoon for our magisters to study further, but I am sure it will prove useful in our struggle against the Amani.\n\nYour help has been invaluable in procuring this gem, and I will see to it that the Farstriders know the name of the {race} who made this find possible.", objectives = "Use the Gift of Naias near the Altar of Naias to summon the water elemental Naias. Defeat him and return to Nemeth Hawkeye at Grom'gol Base Camp with the Heart of Naias.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9460] = { id = 9460, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Combining Forces", description = "Keltus Darkleaf reporting for duty!\n\nOh... who are you, anyhow?  If you are here for my report, I insist you help me first.\n\nI am planning to attack the sentinel spies, but I intend to send in my faithful Whisper as a first strike.  She just needs a scent to hone in on them.\n\nSurely someone of your skill could sneak in and steal something from the sentinel leader?", objectives = "Keltus Darkleaf wants you to pickpocket the Lacy Handkerchief from the Sentinel Leader and bring it to him.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9461] = { id = 9461, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call of Fire", description = "You should know that The Prophet has been asking for you, having heard of your success in your trial. The creation of your fire totem will have to wait until you have spoken with him.\n\nThis is a rare honor; you must hurry to the Exodar to see him at once!", sourceObjective = "Seek out Prophet Velen at the Vault of Lights in the Exodar.", sourceObjectiveStatus = "unverified-source-field" }
quests[9462] = { id = 9462, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call of Fire", description = "{name}! It is time for you to receive further training in the ways of the spirits. You should seek out Tuluun, the shaman at Azure Watch. He can begin your introduction to understanding and harnessing the power of flame.", objectives = "Speak with Tuluun at Azure Watch on Azuremyst Isle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9463] = { id = 9463, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Medicinal Purpose", description = "I have found that lashers milling about on the island hold restorative medicinal properties in their vines. Through proper treatment, the vines can be broken down into a powerful healing ointment. Unfortunately, with so many injured draenei passing through Azure Watch, we are always in short supply.\n\nOur delicate guest was found injured and unconscious by the Crystalbrook only yesterday. If you bring me vines, we may be able to save her.\n\nYou will find root trappers both south and east of Azure Watch.", progress = "I fear that her health is in steady decline.", completion = "Let us hope that this ointment will strengthen her spirit!", objectives = "Anchorite Fateema at Azure Watch wants you to bring her 8 Root Trapper Vines.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9464] = { id = 9464, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call of Fire", description = "Once again you are to be tested, and this time the chaotic element of fire must be understood if you're to create a totem to harness its energies.\n\nTo the northeast on the coast is a sacred place of fire known as Emberglade. Amidst its burned trees stands Temper, a fire elemental of great power, and the one that you must speak with.\n\nGo to him now and may the elemental spirits of Azeroth go with you.", sourceObjective = "Speak with Temper at Emberglade on Azuremyst Isle.", sourceObjectiveStatus = "unverified-source-field" }
quests[9465] = { id = 9465, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call of Fire", description = "One of my brethren, Hauteur, has gone insane, no doubt because of the crash of your ship.  He's begun demanding that the local owlbeasts worship him.\n\nThis will not continue!  None of us would ever impersonate a god!  It falls to you to restore the balance.\n\nFirst, you must retrieve their ritual torch, which has been taken by the crazed wildkin inside Stillpine Hold to the west.\n\nReturn the torch to me.", objectives = "Retrieve the Ritual Torch and return it to Temper at Emberglade on Azuremyst Isle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9466] = { id = 9466, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: Blacktalon the Savage", description = "By order of the Ranger Captain, a reward is hereby offered for the slaying of the vicious rockflayer matriarch known as Blacktalon the Savage.\n\nBlacktalon was last sighted inside a cave in the Great Fissure.  Individuals seeking the reward are to present the creature's claws as proof of the deed.", progress = "You have news regarding Blacktalon?", completion = "You're a brave {class}, {name}.  That savage beast took many of my best hunters' lives.\n\nTake this reward, you've earned it.", objectives = "Bring Blacktalon's Claws to Ranger Captain Venn'ren at Falcon Watch in Hellfire Peninsula.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9467] = { id = 9467, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call of Fire", description = "The owlbeasts of Moonwing Den on Silvermyst Isle, far to the southwest, have been deluded into thinking that Hauteur is a god to be worshipped.  What he truly is, is a fallen elemental who needs to be put out of his misery.  That torch is the key to his downfall.\n\nHauteur regularly demands that these owlbeasts burn an effigy in his honor.  So, when you light it, he will come.  Slay him and bring me the ashes.  Then use the orb in the satchel that I will give you to return to me here.", objectives = "Retrieve Hauteur's Ashes and then return them and the Ritual Torch to Temper at Emberglade on Azuremyst Isle. Remember that you can use the Orb of Returning to teleport back to Temper once you have the ashes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9468] = { id = 9468, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call of Fire", description = "You have done a great thing here today in your pursuit of understanding your relationship to the flame.  Remember to always treat it with the utmost respect lest you get burned.\n\nI saved a portion of Hauteur's ashes for you.  Use them in the creation of your fire totem and remember all that you have learned in their attainment.\n\nNow, return to Tuluun.", objectives = "Deliver Hauteur's Ashes to Tuluun at Azure Watch on Azuremyst Isle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9469] = { id = 9469, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Featherbeard's Endorsement", description = "When I am finally granted an audience with Falstad Wildhammer, I hope to have our strongest advocate among the Wildhammer dwarves at my side, {name}.\n\nFeatherbeard is revered among his people, both for his legendary gryphon training skills and for his wisdom. If anyone can sway Falstad Wildhammer, it is he.\n\nI would go to see him myself, except that I cannot leave the confines of Aerie Peak while awaiting my audience. Visit Featherbeard at his residence to the south and ask if he will speak with me.", completion = "Featherbeard's journal appears to have a large number of recent entries. Leafing back to the beginning of the latest ones, you begin searching for clues about where he might have gone.", objectives = "Go to Featherbeard's Hovel and visit the dwarf if he is at home. If he is not at home, search for evidence of where he can be found.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9470] = { id = 9470, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Gesture of Goodwill", description = "The rugged terrain of the Hinterlands is not only home to the Wildhammer dwarves and their gryphons, but also to a number of forest troll tribes.\n\nThe trolls view the Wildhammers as squatters on their ancestral lands and spare no opportunity to accost the dwarves by attacking the gryphon aeries. One way to prove ourselves in the eyes of the Wildhammer is to help staunch these attacks by killing a Witherbark leader, Witch Doctor Mai'jin, who shelters in a cave at Bogen's Ledge, to the west of Shadra'Alor.", completion = "Well done, {name}. The Wildhammers will be heartened to know that they don't stand against the Witherbark trolls alone. Showing them that the Alliance can prove a reliable partner in protecting the gryphons should lend more weight to our proposition.", objectives = "Ambassador Rualeth at Aerie Peak wants you to slay Witch Doctor Mai'jin and his pet spider Tcha'kaz.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9471] = { id = 9471, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Preying on the Predators", description = "The Wildhammer dwarves act as companions, caretakers, and trainers to the gryphons. The gryphons have no shortage of enemies, especially among the forest troll tribes.\n\nSometimes, though, the threat comes from natural predators, such as wolves. A single animal is no match for a gryphon, but packs have taken to targeting gryphons more often because normal prey is scarce. Culling the wolves can help to reduce their impact on the gryphons and ingratiate us to the Wildhammer.", completion = "<Ambassador Rualeth nods as you give your report.>\n\nYou have done well. The culling of the silvermane will not go unnoticed by the Wildhammer. When I meet with their leaders, I am certain that your deeds will reflect well upon the Alliance. Please accept this coin as a small token of my thanks, {name}.", objectives = "Ambassador Rualeth at Aerie Peak wants you to kill 10 Mangy Silvermane and 5 Silvermane Wolves.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9472] = { id = 9472, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arelion's Mistress", description = "With all the important matters at hand Arelion still found time in his schedule to see a mistress!\n\nIt's all becoming perfectly clear.  Viera Sunwhisper, that filthy wench... we'll show her to never cross a magistrix again.\n\nTake this scroll and find Viera.  Find a way to lure her away from town and use the scroll on her.\n\nArelion mentioned she couldn't resist a particular wine harvested by the cenarion druids.  You might find some at Cenarion Refuge, just inside Zangarmarsh, west of here.", completion = "Excellent!  That little backstabber won't be running off with anyone's husband any time soon.\n\nHere's a little something for your troubles.  I trust we can keep this incident between us, {name}.", objectives = "Magistrix Carinda at Falcon Watch wants you to lure Viera Sunwhisper away from the settlement and then use Carinda's Scroll of Retribution on her.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9473] = { id = 9473, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Alternative Alternative", description = "The girl is too far gone for mere ointments to be effective. There may be another way...\n\nThe forest of Azuremyst holds many secrets, one of those being a rare plant known as the azure snapdragon that some claim to be a panacea - a cure all.\n\nYou can identify the plant by its stark contrast to the other plants of Azuremyst and its need to grow at the base of the azure pine trees. Make haste!\n\nAnd {name}, be wary of the root threshers of the region as they consume snapdragon for sustenance.", progress = "Do not waste time, boy.", completion = "Watch as the plant works its magic.", objectives = "Daedal at Azure Watch wants you to bring him 5 Azure Snapdragon Bulbs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9474] = { id = 9474, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Mark of the Lightbringer", description = "In the short time that I have been on Azeroth I have studied many of its heroes.  Of them all, Uther Lightbringer stands above the rest.  A hero for the ages, in the end Uther was betrayed by his most promising pupil, Arthas.\n\nIn his honor, I would like to return something he lost to his nearby tomb.  It is rumored that the Scarlet Crusade is keeping one of his holy relics atop their guard tower near the gates of Hearthglen.\n\nPlease, {class}, go and retrieve it.", progress = "The Mark of the Lightbringer is a powerful symbol of Uther's faith in the Light.", completion = "Thank you, {class}!  The recovery of this holy symbol means a great deal to myself and others that honor the memory of Uther Lightbringer.", objectives = "Obtain the Mark of the Lightbringer and return it to Anchorite Truuen at Chillwind Camp in the Western Plaguelands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9475] = { id = 9475, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reclaiming the Eggs", description = "Looking over the remains, you surmise that this broken and battered skeleton must be all that is left of Featherbeard. Clutched in one skeletal hand is a torn and stained sheaf of paper. You gently remove and unroll it, revealing a hand-drawn map and a few hastily scrawled notes.\n\nThe map appears to be a rendering of Shadra'Alor and its three temples with 'x' marks in several places, presumably the locations of the stolen eggs. You place the map in your pack for inspection at a safer location.", progress = "The look on your face marks you as the bearer of bad news. What have you discovered?", completion = "<Handing the eggs to the ambassador, you describe the findings at Featherbeard's Hovel and Shadra'Alor.>\n\nThe Witherbark killed Featherbeard?\n\n<Rualeth's face contorts in horror at your description of the dwarf's death and the implications for Rualeth's mission.>\n\nI understand why he felt he had to go in search of the eggs, but I wish he'd thought to bring others along. His death will no doubt enrage Falstad Wildhammer, triggering retaliation against the trolls, and delaying my audience indefinitely.", objectives = "Gather 5 Gryphon Eggs and return them to Ambassador Rualeth at Aerie Peak.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9476] = { id = 9476, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Pursuit of Featherbeard", description = "The journal's most recent entries detail Featherbeard's concern about a growing number of Witherbark troll raids on the Wildhammer gryphon aeries and a rash of egg thefts. A search of the smaller Witherbark settlements in the area appears to have yielded no information.\n\nThe last entry describes Featherbeard's suspicion that a Witherbark witch doctor named Mai'jin is behind the raids. The last, hastily written sentence states the dwarf's intention to travel to Shadra'Alor in search of the eggs.", completion = "Upon the altar is a heap of bones that appear to have belonged to a dwarven male. No identifying features remain, but you decide to search the body for confirmation that these are the remains of Featherbeard.", objectives = "Travel to Shadra'Alor and search for traces of Featherbeard.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9483] = { id = 9483, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Life's Finer Pleasures", progress = "Just because we're on this pilgrimage doesn't mean we have to give up all of life's pleasures.  It's been ages since I had a good wine.\n\nI'd literally kill for a bottle of cenarion spirits!\n\nI know, I know, how unfashionable of me to enjoy a drink brewed by night elves.", completion = "You know, maybe we can become friends after all.  Follow me; we don't want to have to share this with the others now, do we?" }
quests[9484] = { id = 9484, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taming the Beast", description = "You have undoubtedly hunted and slain beasts for both your defense and sustenance, yet to befriend them and harness their strengths is only now within your grasp.  This I can teach you.\n\nTake this magical taming rod that allows a wild animal to temporarily bond and fight beside you.  Begin with the crazed dragonhawk, a nearly docile bird found just outside of Farstrider Retreat.  Return to me when this is done.", objectives = "Use the Taming Rod to tame a Crazed Dragonhawk, and then return to Lieutenant Dawnrunner.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9485] = { id = 9485, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taming the Beast", description = "You have done well, {name}.  Your understanding of the wild grows quickly.\n\nThe mistbat is a clever hunter, combining the swiftness of the dragonhawk and the ferocity of the springpaw.  Mistbats are found just across the Elrendar River to the south, preying on hapless travelers who wander into the Ghostlands.\n\nUse this final taming rod to befriend a mistbat and return to me when you have finished.You will learn:", objectives = "Use the Taming Rod to tame a Mistbat, and then return to Lieutenant Dawnrunner.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9486] = { id = 9486, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taming the Beast", description = "The elder springpaw is an efficient and swift hunter.  In attempting to befriend one, it sees you as prey.  Do not be dissuaded.\n\nUse the taming rod to bring the great cat to your side and hunt beside it.  They are found throughout Eversong Woods, some very close to the lodge.  When you have learned enough, return to me.", objectives = "Use the Taming Rod to tame an Elder Springpaw, then return to Lieutenant Dawnrunner.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9487] = { id = 9487, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arcane Reavers", description = "Arcane reavers are magical creations of brute strength.  They are heavily armored and deliver stunning blows.  You, however, can bypass their defenses and avoid their attacks.  Your spellcraft is not without many advantages, {name}.\n\nTravel to Dawnstar Spire and blast apart the arcane reavers.  From their remains, collect the crystallized fragments of magical energy and return to me.  Dawnstar Spire is found to the east, across the lake.", progress = "Didn't get too close to the brutes, I hope?", completion = "Such a waste, using magic to construct beings of physical strength.  I always thought that's why we allied with the lesser races, after all.\n\nYou were good to destroy them so we can use what remains for a more suitable purpose.", objectives = "Arcanist Vandril wants you to collect 10 Arcane Fragments for him.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9488] = { id = 9488, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Simple Robe", description = "The arcane fragments you collected will do nicely.\n\nNicely for what, you ask?  For making a splendid robe fit for a {class} like yourself!\n\nAll we need now is some linen cloth and a spindleweb silk gland.  You can find the silk gland from any spindleweb spider, preferably after killing them.", progress = "The robe cannot be completed without the necessary supplies.  But you knew that, didn't you?", completion = "You really don't need to know the intricacies of crafting a magical robe, {name}, you just need to know what to bring me.\n\nAnd let me be honest, you brought enough for several robes.  The profit I'll make should more than cover the costs to make your robe, and even enough to buy myself something nice.  Looks like the thanks belong to you!", objectives = "Arcanist Vandril wants you to bring him 15 Linen Cloth and a Spindleweb Silk Gland.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9489] = { id = 9489, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cleansing the Scar", description = "{name}, it is good you are here.  The Scourge attack our city with such endless hate that I fear the morale of our guard is breaking.\n\nHurry to the Dead Scar just south of the city where Jaela and her rangers stand ready.  Fill them with the power of the Light through your blessings.", objectives = "Cast Power Word: Fortitude on 6 Eversong Rangers in the Dead Scar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9490] = { id = 9490, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Rock Flayer Matriarch", description = "Rock flayers are mean, nasty, violent creatures.  But the plain ones are like tame beasts when compared to their matriarch, Blacktalon the Savage.\n\nMy cousin got eaten by her and it wasn't pretty.  I swore that one day Blacktalon would pay for that.  You bring back proof of that monster's death and I will give you my life's savings.  Deal?\n\nYou'll find her inside a cave in the Great Fissure.  Good luck!", progress = "Did you bring back proof of Blacktalon's death, {name}?", completion = "Yes, I remember these sharp claws!\n\nTake this reward, {name}.  That was a dangerous task you just did.  You deserve every bit of this reward.", objectives = "Obtain Blacktalon's Claws from Blacktalon the Savage at the Great Fissure and bring it to Ikan at the Temple of Telhamat in Hellfire Peninsula.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9491] = { id = 9491, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Greed", description = "A rich, and I mean filthy rich, merchant came through here yesterday talking about some ring of \"immense archeological importance\" locked in one of the countless burial chests found in the Amani Catacombs.  When he wasn't talking about the ring, he was talking about how much he'd pay for it.\n\nTell you what, I'll front the thieves' tools, and if you manage to bring the ring back, I'll pay you enough to buy ten rings of your own!", objectives = "Eralan in Tranquillien wants you to retrieve the Pitted Gold Band from the Amani Catacombs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9492] = { id = 9492, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Turning the Tide", description = "The permanence of the orcish threat is one of the sad truths of Outland. There was a time when we Sons of Lothar believed we'd purchased Honor Hold's safety with our blood, but there was to be no peace.\n\nThe Sons will yield to no orc - green, brown, and now red - we will overcome them or die trying. If we are to have any expectation of victory, we must take the fight to them in Hellfire Citadel. Bring me the weapon of their self-styled 'Warchief' Kargath Bladefist and you will be well rewarded.", progress = "Have you returned with proof of 'Warchief' Kargath Bladefist's demise?", completion = "Well done, {name}. With your victory in Hellfire Citadel, we have struck a major blow against the orcs.\n\nI must speak with Field Commander Romus about following up and ensuring that the orcs stay on the defensive. Now that we've been reinforced, we can do far more than simply defend Honor Hold.", objectives = "Bring Warchief Kargath's Fist to Force Commander Danath Trollbane in Honor Hold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9493] = { id = 9493, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pride of the Fel Horde", description = "We know precious little about the Fel Horde presence in Hellfire Citadel and our information has come at the cost of many lives.\n\nFel Horde troops under the command of Kargath Bladefist are a brutal, battle-hardened lot fortified by foul magics. The elite of this force, the Shattered Hand legionnaires, champions, and centurions are feared by the regulars and serve as an officer corps.\n\nTargeting and eliminating them is a necessary first step in any successful assault on the Fel Horde's leadership.", completion = "That is excellent news, indeed, {name}. With progress to report from Hellfire Citadel, perhaps we can afford to turn our attention to the Fel Horde presence other parts of the peninsula and Outland as a whole.", objectives = "Field Commander Romus at Honor Hold wants you to kill 8 Shattered Hand Legionnaires, 4 Shattered Hand Centurions, and 4 Shattered Hand Champions.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9494] = { id = 9494, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fel Embers", description = "The stuffy academics of Azeroth have cowered in their towers for too long and it's fallen to me to show them what cutting edge research is! They're afraid to play with fire and that's exactly what I intend to do, once I get my hands on the fire, that is.\n\nWithin Hellfire Citadel's Shattered Halls, Grand Warlock Nethekurse performs unrivaled magical feats augmented by the powers of a pair of strange braziers. Using the vessel he uses to contain these fel embers, capture one and bring it back to me, {name}.", progress = "<Magus Zabraxis glances over at Amythiel Mistwalker and lowers her voice.>\n\nDid you bring the, err, ember?", completion = "Well done! I can't hope to replicate the feats of Grand Warlock Nethekurse, nor should I aspire to, but we would be fools to ignore the power of the fel embers.\n\nHowever, there are those who would forbid the type of research I'm about to embark upon, and for that reason, I must keep my efforts secret. Please do not speak of this to anyone, {name}.", objectives = "Magus Zabraxis at Honor Hold wants you to bring her a Fel Ember.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9495] = { id = 9495, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Will of the Warchief", description = "The struggle to free the orcish people from our tainted blood has not been easy, {name}. Warchief Thrall has seen too many orcish heroes laid low by fate's hand. Now, it seems Kargath Bladefist numbers among them.\n\nIn the Shattered Halls of Hellfire Citadel, Kargath has claimed the title of 'Warchief' of the Fel Horde. With an army of crazed, bloodthirsty fel orcs at his back, he won't rest until Thrallmar is destroyed. Warchief Thrall has commanded us to defeat Kargath and his forces at all costs.", progress = "Have you proof of Kargath Bladefist's defeat?", completion = "You have done well, {name}. In his prime, Kargath Bladefist was a fine warrior, a hero and example to his people.\n\nHis death is a blow to us all, but especially to Warchief Thrall. Whatever happened to him in his final days, we should not forget the orc Kargath once was, nor the lessons to be learned from his downfall.\n\nFor your service to the Horde, {name}, you are to be rewarded with your choice from among these weapons.", objectives = "Bring Warchief Kargath's Fist to Nazgrel in Thrallmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9496] = { id = 9496, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pride of the Fel Horde", description = "Overlord Maimfist's insults aside, {name}, this Fel Horde is nothing to be trifled with.\n\nFrom what we know, Fel Horde troops under the command of Kargath Bladefist are a brutal, battle-hardened lot fortified by foul magics. The elite of this force, the Shattered Hand legionnaires, champions, and centurions are feared by the Fel Horde regulars and serve as an officer corps.\n\nTargeting and eliminating them is a necessary first step in any successful assault on the Fel Horde's leadership.", completion = "Excellent job, {name}. With the legionnaires broken, it will be easier to face the Fel Horde on the battlefield, though they remain a formidable enemy.", objectives = "Shadow Hunter Ty'jin at Thrallmar wants you to kill 8 Shattered Hand Legionnaires, 4 Shattered Hand Centurions, and 4 Shattered Hand Champions.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9497] = { id = 9497, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Emblem of the Fel Horde", description = "When word of the so-called 'Fel Horde' reached the Warchief's ears, he was both furious and greatly saddened. Like Rend's pretenders before them, this false Horde too will fall, and its banner will adorn the wall of Grommash Hold as a testament to the Warchief's might.\n\nIt falls to you to carry out the Warchief's will in this matter, {name}. It will not be an easy task, for the banner is guarded by a champion of this Fel Horde, known as Warbringer O'mrogg, and he will not yield his charge without a fight.", objectives = "Slay Warbringer O'mrogg and capture the Fel Horde Banner, then return it to Overlord Hun Maimfist at Thrallmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9498] = { id = 9498, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Falcon Watch", description = "My people recently finished building Falcon Watch, a base of operations in the southwestern region of Hellfire Peninsula - beyond Hellfire Citadel.  You are welcome there as an ally, {name}.\n\nIf you're looking for work, go there and tell Ranger Captain Venn'ren that I sent you.  He will see to it that you're given tasks worthy of someone of your caliber.", completion = "Welcome to Falcon Watch, {race}.  All our Horde allies are welcome here, especially those recommended by Martik.", objectives = "Report to Ranger Captain Venn'ren at Falcon Watch in Hellfire Peninsula.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9499] = { id = 9499, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Falcon Watch", description = "What are you still doing here, {name}?  Didn't you hear we built a proper sin'dorei outpost here in Hellfire Peninsula?\n\nSurely you'd rather be among fellow blood elves and away from all this... smell.  You'll find Falcon Watch in the southwest, beyond Hellfire Citadel.  Report to Ranger Captain Venn'ren; he will take care of you.\n\nThe road ahead is dangerous and heavily patrolled by Alliance scouts.  I would recommend travelling with companions.  Blood elves, preferably.", completion = "Welcome to Falcon Watch, brother.  Many other blood elves haven't been fortunate enough to make it this far.\n\nIt's a terrible shame; our work in Outland has just begun.", objectives = "Travel to Falcon Watch in the southwest of Hellfire Peninsula and report to Ranger Captain Venn'ren.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9500] = { id = 9500, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call of Water", description = "It's been a while since last you were tested.  Farseer Nobundo has been asking for you.  You must have grown greatly in wisdom because you are being called to learn the mysteries of the element of water.\n\nYou remember where to find him at the Crystal Hall inside of the Exodar, right?", completion = "We meet again. I have been watching your progress from afar, {class}, and I am pleased.\n\nThe time has come for you to commune with the element of water, to learn its mysteries and give yourself over to the water so that you might in turn learn to master it.", objectives = "Speak with Farseer Nobundo at the Crystal Hall inside the Exodar on Azuremyst Isle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9501] = { id = 9501, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call of Water", description = "A powerful water elemental named Aqueous has requested your presence.  It would seem that there is a great imbalance occurring in the water element on Bloodmyst Isle.  Not surprising given the unnatural predilections of the blood elves.\n\nYou will find Aqueous in a hidden reef under the waves off the northern shore of Bloodmyst Isle.\n\nTake this potion; it can help you to get to her once you get into the water near the reef.", objectives = "Speak with Aqueous in the Hidden Reef at Bloodmyst Isle.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9502] = { id = 9502, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call of Water", description = "It's been a while since last you were tested.  Farseer Nobundo has been asking for you.  You must have grown greatly in wisdom because you are being called to learn the mysteries of the element of water.\n\nYou remember where to find him at the Crystal Hall inside of the Exodar, right?", objectives = "Speak with Farseer Nobundo at the Crystal Hall inside the Exodar on Azuremyst Isle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9503] = { id = 9503, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call of Water", description = "In balance with the other elements, water is the source and sustenance of all living things.  It gives and nurtures life, and all rely upon it for their existence.  Yet, when polluted, it also brings life to an end.\n\nWe must determine the extent of the damage that has been done.  To the southwest is one such contaminated body of water that has come to be known as the Foul Pool.  Travel there and extract the foul essence from the water spirits that inhabit the pool.", objectives = "Collect 6 Foul Essences and return them to Aqueous in the Hidden Reef at Bloodmyst Isle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9504] = { id = 9504, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call of Water", description = "It is worse than I feared. The corruption is very potent and if unchecked it could spread to the ocean currents and be carried throughout all of Azeroth!\n\nWe are going to need a sample of the purest water to counter this malignancy. There are ruins on the untainted portion of this island, to the southeast. Go there, where the Wrathscale naga reside, and take from their fountain.\n\nUse this bota bag to gather the sample. Hurry, {name}!", objectives = "Fill the Empty Bota Bag and then return to Aqueous in the Hidden Reef at Bloodmyst Isle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9505] = { id = 9505, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Prophecy of Velen", description = "The Prophet spoke of this day: That on this island, in this new world, our allies would find us.\n\n\"We will be tested. They will ask that we pay for the sins of our fathers...\"\n\nAt the time, I did not understand the meaning behind his words, but seeing this creature and her reaction to us, it is now coming into focus. The corruption of our people has been felt even here.\n\nVenture south. It is there that we found this being. Find its kin and tell them of our people.", completion = "You say that you've found one of our crew and that she is injured? I will send one of my crewmen to your village immediately!", objectives = "Daedal wants you to travel south and seek out the people that the injured creature mentioned.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9506] = { id = 9506, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Small Start", description = "I am Admiral Odesyus of Alliance Naval Command. Our ship was forced to port on your island due to an infestation of sorts. It's embarrassing to even talk about, but goblins somehow managed to stow away in the holds of both of my ships.\n\nLast night, while most of the ship's crew was asleep below deck, they struck!\n\nStranger still, they took our navigation gear and jumped ship!\n\nThey disappeared into the thicket, east of here. Will you go in search of our gear? It will make for a strong gesture.", progress = "Any luck, stranger?", completion = "You're a resourceful one! With our navigation gear, we can figure out just how far we've veered off course.\n\nBut wait, what's this? There's something rolled up in the map. Let me see...\n\nThese are orders from Mogul Razdunk of the Venture Company. According to these plans, they're here to strip-mine the island of the crystal wreckage, then hijack our ships once they're finished.\n\nBy Bronzebeard's bushy brow! This is why they forced us to land? How could they know of our plans?\n\nI smell a traitor...", objectives = "Admiral Odesyus at Odesyus' Landing wants you to recover the Nautical Compass and Nautical Map stolen by the Venture Co.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9508] = { id = 9508, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call of Water", description = "I have determined where the corruption is coming from.  It is the by-product of some demented research and you're going to put an end to it!\n\nJust to the southwest of the Foul Pool is a small camp.  There you will find the 'research' of Tel'athion the Impure.  This is where he produces the filth that has been seeping into the island's water.\n\nUse the pure water you obtained from Ashenvale to destroy his cache of barrels.  That will be sure to bring him out.\n\nWe will have an end to this!", objectives = "Bring the Head of Tel'athion to Aqueous in the Hidden Reef at Bloodmyst Isle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9509] = { id = 9509, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call of Water", description = "I held back a little of the water from Ashenvale, not because I doubted your ability to deal with the situation.  Rather, I knew that you would succeed, and I wanted to make sure that you had something special to take back to Nobundo.\n\nHere, {name}, take this flask of pure water.  It will ensure that you receive a very powerful water totem.\n\nFarseer Nobundo awaits your return at the Exodar.You will learn:", objectives = "Take the Flask of Purest Water to Farseer Nobundo inside the Exodar on Azuremyst Isle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9510] = { id = 9510, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bristlehide Clefthoof Hides", description = "So you're looking to make yourself useful?  We're in very short supply of clefthoof hides, {name}.\n\nIf you go southwest of here you'll find bristlehide clefthoof in abundance near a place called Falcon Watch.  Their hides are ideal for leatherworking.  Bring me a stack of them and I'll reward you appropriately.", objectives = "Provisioner Braknar at Mag'har Post in Hellfire Peninsula wants you to bring him 5 Bristlehide Clefthoof Hides.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9511] = { id = 9511, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kargath's Battle Plans", description = "<TXT>The documents you found on Kargath's body detail plans on what appears to be a massive invasion on Honor Hold." }
quests[9512] = { id = 9512, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cookie's Jumbo Gumbo", description = "The Admiral be right, ye are a resourceful one. Mayhap ye could help Cookie out?\n\nIf I serve the crew chicken for dinner again, I'll be sent to the brig fer sure.\n\nI noticed that thar be crawlers all along the coastline - lots o' crawlers! Bring me crawler meats and I'll be forever indebted to ya.\n\nHelp a reformed pirate out?", progress = "Arrr... Yarr... Shiver me timbers... Er, sorry lad, I gotta practice me pirate lest I forget it...", completion = "Bless yer heart, stranger. This'll go a long ways in liftin' the morale o' the crew.", objectives = "\"Cookie\" McWeaksauce at the Odesyus' Landing wants you to bring him 6 Skittering Crawler Meat.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9513] = { id = 9513, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reclaiming the Ruins", description = "While some may look at our current predicament as an unfortunate turn of events, I sense that we are here for a reason. The invisible hand of fate has pushed us in this direction. The reason why will become evident in time.\n\nTo the west lies an ancient night elf city, now in ruin and overrun with naga. It would be remiss of me to sit idly by as the naga tainted my ancestral lands.\n\nYou have shown yourself a capable {class}. Honor my people and cleanse the ruins of their unwelcome inhabitants.", completion = "Elune be praised! The restless spirits may find tranquility after all.", objectives = "Priestess Kyleen Il'dinare at Odesyus' Landing on Azuremyst Isle wants you to kill 5 Wrathscale Myrmidons, 5 Wrathscale Naga and 5 Wrathscale Sirens.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9514] = { id = 9514, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rune Covered Tablet", description = "You cannot make out any of the symbols on the tablet. Perhaps the priestess would be able to decipher the mysterious runes.", progress = "You've found something?", completion = "I can't read these runes but I know someone who can...", objectives = "Take the Rune Covered Tablet to Priestess Kyleen Il'dinare at Odesyus' Landing on Azuremyst Isle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9515] = { id = 9515, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warlord Sriss'tiz", description = "A naga invasion would be disastrous, {name}. I've seen what naga can do and I would not want to see such a catastrophe befall any being. If I were to guess, this Warlord Sriss'tiz will be hidden in a cave - probably along the coast to the west.\n\nFind Warlord Sriss'tiz and put an end to his reign.", completion = "With Warlord Sriss'tiz dead, the possibility of a naga invasion is now only a distant memory. We are safe, for the time being...\n\nI must admit, I was wrong to think badly of you, {name}. You have shown that you are nothing like the filth that was Archimonde. Accept this as a gift from the night elves.", objectives = "Priestess Kyleen Il'dinare at Odesyus' Landing on Azuremyst Isle wants you to kill Warlord Sriss'tiz.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9516] = { id = 9516, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Destroy the Legion", description = "I will not tolerate their existence on this world! The Burning Legion all but destroyed our race and we fell back to settle a new home on a new world. Then they came again and we retreated, over and over.\n\nNo more!\n\nThere is a remnant of the Legion to the south and west in the regions known as Felfire Hill, Demon Fall Canyon and Demon Fall Ridge. They are what is leftover from a force that once long ago invaded this world.\n\nGo and destroy as many as you can before it is too late!", completion = "You have my respect and thanks, {class}.  Perhaps we'll be able to create a new home here without having to worry about the Burning Legion yet again.", objectives = "Slay any 15 demons at Felfire Hill, Demon Fall Canyon, and Demon Fall Ridge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9517] = { id = 9517, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Shameful Waste", description = "Welcome to Forest Song, {class}. Where you see tents, there will one day be buildings, but such ambition requires a steady stream of materials. I cannot bring myself to order our workers to fell any of the ancient trees of this grove, but our neighbors to the west have no such reverence for the forest.\n\nWe shall reclaim the tainted wood from Satyrnaar to the west. Take the wood to Gnarl at the Warsong Lumber Camp. He is an Ancient who will purify it for our use.", progress = "<The ancient creaks as it turns toward you.>\n\nArchitect Nemos said that you might be bringing wood salvaged from the deforesters' encampment and befouled Satyrnaar.", completion = "Wood cut with orcs' crude blades is warped as surely as that exposed to elemental extremes. Nothing sound can be built with it, but I shall purify it and return it to Architect Nemos and his men for their use. Some good will come from this tragedy, after all.", objectives = "Collect 5 Satyrnaar Fel Wood.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9518] = { id = 9518, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Agents of Destruction", description = "The Warsong Lumber Camp is a blight upon an embattled landscape. Every time we make progress in halting their operations, Overseer Gorthak orders his loggers to redouble their efforts!\n\nNow, the orcs are cutting more wood than they can possibly use, leaving it to rot while their blades bite into fresh trees! This is an affront to all we stand for, {name}, and we will show them that we'll not suffer further destruction of our lands!\n\nGo, and do not rest until Overseer Gorthak and his minions are dead!", completion = "At last we have sent a message that the orcs won't dare ignore. Any overseer or foreman who sets foot within the camp to replace Gorthak will feel my wrath!\n\nWe must press our advantage, {name}, and never rest until the Warsong Lumber Camp is a distant memory and a glade of trees stands upon that ground.", objectives = "Slay Overseer Gorthak and any other 12 Horde at the Warsong Lumber Camp.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9519] = { id = 9519, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lost Chalice", description = "The area to our west, now called Satyrnaar, was once a prominent shrine built by my people. It housed a priceless relic, the Chalice of Elune, entrusted to the shrine's keepers by the priests of Elune. Pilgrims once traveled to the shrine to experience the healing powers the chalice was rumored to hold.\n\nThese stories might be nothing but old wives' tales, but if there is any truth to them, the relic may hold the key to rejuvenating the wounded forest. I must know, {name}.", progress = "Can you feel it, {name}, the touch of corruption upon the wind? If we do nothing, it will continue to advance. That is why I seek the Chalice of Elune. Were you able to find it?", completion = "Excellent work, {name}. There is certainly a latent power here, one that not even constant exposure to the corruption of the satyr can dim. Do you see how it still shines, after all these years?", objectives = "Obtain the Chalice of Elune.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9520] = { id = 9520, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Diabolical Plans", description = "The demon dropped this parchment, which is amazingly written in the Common tongue!  The ones mentioned in it, Diathorus and Gorgannon, are the two infamous dreadlords that control the demons hereabouts.\n\nThe plans detail preparations for a demonic attack on Forest Song to the north; the location where a new draenei settlement is being established.\n\nPerhaps Vindicator Vedaar at the Warsong Lumber Camp would be interested in these?", progress = "What do you have there, sir?", completion = "By the Seven Crystals of Ata'mal, this cannot be!  They plan to attack us here at Forest Song?!\n\nNot on my watch!\n\n<Vindicator Vedaar crumples the demon-scrawled plans in his fist.>\n\nNo.  We will not allow this to happen!", objectives = "Deliver the Diabolical Plans to Vindicator Vedaar at the Warsong Lumber Camp in Ashenvale.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9521] = { id = 9521, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Report from the Northern Front", description = "The battle against the Horde isn't being waged from Raynewood Tower alone, {name}. There's a more substantial Silverwing Sentinel presence at Silverwing Grove to the southeast, near the border with the Barrens. From the grove, Sentinel Farsong directs our efforts against those who would destroy our lands.\n\nI'm a bit late in sending my latest report to her, but also hesitant to leave the tower unattended.\n\nI am in dire need of your help in getting this report to her as soon as possible!", progress = "What's that you have there, {class}?", completion = "Thank you for delivering this report, {class}. From what Sentinel Luciel writes, it seems our worst fears have come to pass. With each advance we make, the Horde appears more determined to do as much damage as possible.\n\nWe can't afford to back down; the fate of our ancestral lands hangs in the balance. With more people like you on the frontlines, I'm certain we could triumph. Will you join our fight?", objectives = "Deliver Sentinel Melyria's report to Sentinel Farsong at Silverwing Grove in Ashenvale.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9522] = { id = 9522, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Never Again!", description = "{name}, it falls to you to see that this attack by the Burning Legion never comes to pass. You must go and slay their leaders.  Without them the demons will be mindless.\n\nYou will find Gorgannon in Demon Fall Canyon south beyond Felfire Hill, near Mannoroth's floating, broken spear.\n\nDiathorus the Seeker resides somewhere in the barrow den atop Demon Fall Ridge. To find the ridge, look for a ramp up from Demon Fall Canyon near the Horde's monument to Grom Hellscream.\n\nBring me their weapons.", completion = "Never again will the Burning Legion threaten us here!  You have delivered us from a fight we very likely would have lost, {class}.\n\nI give you thanks and the deepest gratitude of the Hand of Argus.  It honors me to have you at our side.", objectives = "Obtain Gorgannon's Flaming Blade and the Seeker's Fel Spear.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9523] = { id = 9523, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Precious and Fragile Things Need Special Handling", description = "The priestess tells me that the ruins to the west are what's left of a night elf civilization. That got me thinking about what my pappy used to always say about night elf ruins, \"Sonny, whenever you see night elf ruins, night elf relics are sure to be close by.\"\n\nNow what kind of a dwarf would I be if I didn't hire the first person I saw to go digging up night elf relics for me? Now get going!", progress = "Don't come back without some ancient relics.", completion = "My pappy would be proud! His boy strikes it big at the first set of night elf ruins he comes across... With your help, of course. Yes, don't worry, I won't leave you out of the discovery. Your name is {name}, right? They'll learn all about you in Ironforge.", objectives = "Archaeologist Adamant Ironheart at Odesyus' Landing on Azuremyst Isle wants you to bring him 8 Ancient Relics.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9524] = { id = 9524, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Imprisoned in the Citadel", description = "Alliance, here?!  Listen carefully, {class}.\n\nKargath has captured several of our soldiers.  Captain Alina, an important officer is among them.  You must try to save her before she is executed.\n\nDon't worry about me, I'll find a way out as soon as I catch my breath.", completion = "I thank you, {name}.  I must admit I didn't expect a rescue party to be on its way.\n\nI will round up the remaining prisoners and lead them back to Honor Hold.", objectives = "Rescue Captain Alina inside Hellfire Citadel before she is executed.\n\nThis quest must be completed in Heroic dungeon difficulty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9525] = { id = 9525, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Imprisoned in the Citadel", description = "I was fortunate to escape Kargath's prison today, {name}.  Several prisoners are scheduled to be executed, an important officer among them.\n\nIt would be a huge blow against our forces if Captain Boneshatter was slain.  You must do what you can to rescue him.  I'm too weak to go on...", completion = "You've brightened my day, {class}.  When I die, I will make sure it's in the battlefield... covered in the blood of my opponents and taking them down with me.", objectives = "Rescue Captain Boneshatter inside Hellfire Citadel before he is executed.\n\nThis quest must be completed in Heroic dungeon difficulty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9526] = { id = 9526, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reclaiming Felfire Hill", description = "Little one, to the southwest is an area of Nightsong Woods that has in recent times come to be called Felfire Hill. It is very sad to see the demons crawling over it, spreading their corruption.\n\nWould you do something to help take back the land?\n\nI have a number of seeds that I have been saving for such a purpose. Take them to Felfire Hill and plant them in the fertile dirt mounds.", completion = "Good.  Though it may take a great deal of your years for the seedlings to grow into ancients, in the fullness of time they will aid us in our fight against the demons at Felfire Hill.\n\nGo in peace, little brother.", objectives = "Plant 8 Tree Seedlings in the Fertile Dirt Mounds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9527] = { id = 9527, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "All That Remains", description = "We had lived peacefully among the Owlbeasts of this island for many years. You can imagine my surprise when they stormed the beach and attacked us.\n\nI fought tooth and nail but was easily overpowered. As I blacked out from the vicious blows that I had been dealt, I prayed that my family not suffer.\n\nWhen I awoke, all was quiet. The sand was soaked red with blood - their blood. They were devoured whole.\n\nI care not for vengeance, {name}. I only ask that their remains be returned to me for proper burial.", progress = "My wife was named Thalrisa and my daughter, Magwin.", completion = "Thank you, {name}. Their spirits will be at peace now.", objectives = "Cowlen on Azuremyst Isle wants you to recover the Remains of Cowlen's Family.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9528] = { id = 9528, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Cry For Help", description = "My family was attacked by the murlocs and owlkin of this island several weeks ago. I managed to escape but I think that both my mother and father have been slain. I don't know what I'm going to do now, but I must try and get back to my home - or what's left of it... Will you help me get through the forest?", completion = "<Tears of joy stream down Cowlen's face.>\n\nHow can I ever repay you for this, {name}? Please, take this heirloom. It symbolizes a sacred bond of friendship, trust and love amongst night elves. You are a brother to me - from this day until the end of time...", objectives = "Escort Magwin through the island to her home.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9529] = { id = 9529, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Stone", description = "While I'm certain your imp has proven a useful and sometimes entertaining servant, it is time you mastered a more powerful demon: the voidwalker.\n\nTravel down the Dead Scar until it is crossed by the Elrendar River.  Just south of the river, locate one of the blue glowing stones and take it.  Your path will be revealed there.", completion = "As you gaze into the stone, your vision begins to swirl...", objectives = "Obtain a Voidstone from the Dead Scar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9530] = { id = 9530, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "I've Got a Plant", description = "I've wondered about this for some time now, but this proves it to be true.\n\nThere is a traitor among us.\n\nThe plans left behind by the goblins document the conspiracy. Since I don't know who it could be, I'm going to need your help in finding the traitor. None of my crew can be trusted.\n\nIf this is going to work, I'm going to need a hollowed out tree and leaves. Search near the loggers north of us for the tree. You'll need to find the leaves by yourself. Check the forest.", progress = "I love it when a plan comes together...", completion = "I must warn you, what I ask of you next will be dangerous. I won't think less of you if you decide not to help me out, {name}.", objectives = "Admiral Odesyus at Odesyus' Landing on Azuremyst Isle wants you to bring him a Hollowed Out Tree and 5 Piles of Leaves.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9531] = { id = 9531, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tree's Company", description = "According to the plans, the traitor and the leader of the goblins, Geezle, are to meet at a cove on the western island. I need you to be at that meeting, {name}.\n\nRemember the tree and leaves? You're going to wear them! It's a perfect disguise.\n\nGo to the cove and look for a naga flag. If the flag is there, it means a meeting is planned. Use the disguise kit when you see the flag and wait. Eventually the traitor will show up. Let the meeting finish then return to me with the identity of the scoundrel.", progress = "That traitor is going to wish he never messed with Alliance Naval Command!", completion = "I can't believe it! It was the gnome all along... I should have known!", objectives = "Admiral Odesyus at Odesyus' Landing on Azuremyst Isle wants you to observe the meeting that is to take place between Geezle and the traitor.\n\nReturn to him when you know the identity of the traitor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9532] = { id = 9532, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Find Keltus Darkleaf", description = "{name}, one of our scouts has taken too strong an interest in his duties.  He surveys our enemies relentlessly, but sends no reports of his findings.\n\nYou must find this spy, Keltus Darkleaf, convince him to hand over his report and return it to me as swiftly as possible.  He can be found far to the southwest, where the Elrendar River forks and flows around Goldenmist Village.  The night elves of An'daroth are his quarry, and he won't be far from them.", sourceObjective = "Locate Keltus Darkleaf.{name}, one of our scouts has taken too strong an interest in his duties. He surveys our enemies relentlessly, but sends no reports of his findings.\n\nYou must find this spy, Keltus Darkleaf, convince him to hand over his report and return it to me as swiftly as possible. He can be found far to the southwest, where the Elrendar River forks and flows around Goldenmist Village. The night elves of An'daroth are his quarry, and he won't be far from them.", sourceObjectiveStatus = "unverified-source-field" }
quests[9533] = { id = 9533, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Helping Hand", description = "Under the supervision of Architect Nemos and Vindicator Vedaar, my people are revitalizing an old night elf outpost in the eastern part of Ashenvale.\n\nThe task of building won't be easy, {name}, for the challenges and enemies they face are many. I know Architect Nemos and his compatriots at Forest Song would appreciate any help they can get, and he has asked me to send any interested <men/women> his way.\n\nSpeak to me again and I will arrange for fast transport for you to their location.", sourceObjective = "Speak with Architect Nemos at Forest Song in Ashenvale.\n\nVindicator Palanaar can offer you a ride to get you there more swiftly.", completion = "It's good to see another new arrival here at Forest Song.\n\nVindicator Palanaar is sending as much help as she can muster and each set of hands is appreciated.\n\nTake a look around, {class}. It may not be much now, but with time and help from our night elf allies, we'll build a settlement worthy of calling home. There is much to be done here and any help you can provide would be welcome.", sourceObjectiveStatus = "unverified-source-field" }
quests[9534] = { id = 9534, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Destroy the Legion", description = "The remains of the demonic Burning Legion have been a thorn in our side for far too long!\n\nNo more!\n\nThe demons are attacking from the areas known as Felfire Hill, Demon Fall Canyon and Demon Fall Ridge to the east.\n\nGo and destroy as many as you can to bring glory to both yourself and the Horde!", completion = "That's better!  There's nothing quite like ridding our world of a demon.  And they make for worthy opponents as well, unlike the weak races of the Alliance.", objectives = "Slay 15 of any demon type at Felfire Hill, Demon Fall Canyon, or demon Fall Ridge and then return to Valusha at Splintertree Post in Ashenvale.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9535] = { id = 9535, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Diabolical Plans", description = "The demon dropped this parchment, which is amazingly written in the Orcish tongue!  The ones mentioned in it, Diathorus and Gorgannon, are the two infamous dreadlords that control the demons hereabouts.\n\nThe plans detail preparations for a demonic attack on Splintertree Post to the northwest.\n\nYou're certain that Valusha at Splintertree Post would be interested in these.", progress = "What do you have there, scout?", completion = "Dreadlords!  They plan to attack us here at Splintertree Post?!\n\nNot while I still draw breath!\n\n<Valusha crumples the demon-scrawled plans in her fist.>\n\nNo.  We will not allow this to happen!  They are a blight upon our world!", objectives = "Deliver the Diabolical Plans to Valusha at Splintertree Post in Ashenvale.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9536] = { id = 9536, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Never Again!", description = "{name}, you will see to it that this attack by the Burning Legion never comes to pass!  Go and slay these dreadlords!  Without them the rest of the demons are essentially mindless.\n\nYou will find Gorgannon in Demon Fall Canyon south beyond Felfire Hill, near Mannoroth's floating, broken spear.\n\nDiathorus the Seeker resides somewhere in the barrow den atop Demon Fall Ridge.\n\nReturn to me with their weapons as proof of your deeds.", completion = "Never again will the Burning Legion make slaves of the orcs, or any other race of the Horde!\n\nBravely fought, {class}!  You have the true heart of the Horde beating inside of you!  You give us much honor!", objectives = "Obtain Gorgannon's Flaming Blade and the Seeker's Fel Spear.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9537] = { id = 9537, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Show Gnomercy", description = "Spark must be brought to justice!\n\nI need you to go down to the beach and find that deceitful gnome. Once you find him, get whatever information you can out of him!\n\nIf a high ranking official of the Alliance has committed treasonous acts, who knows how many others are corrupt?\n\nAnd {name}, use force if you have to...", progress = "Did you find the lying dog?", completion = "Incredible! This was all part of their master plan!\n\nThis information must reach the king and your own leaders. The implications are staggering.", objectives = "Admiral Odesyus at Odesyus' Landing wants you to recover the Traitor's Communication from Engineer \"Spark\" Overgrind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9538] = { id = 9538, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Learning the Language", description = "I think I've cracked it, {name}!\n\n<Aurren points to the totem.>\n\nAll that we need to know about the Stillpine furbolg language is imprinted on their totems. With just a rudimentary understanding of how their symbols work, we can study the totems and learn to communicate with the furbolgs.\n\nI've written down the basics of the symbol matrix on this parchment. Study it and then examine the totem. It should lead you to the next language totem.\n\nSpeak to Arugoo when you return an educated {race}!", progress = "You can hear a low-pitched hum emanating from the totem.", completion = "The totem has various primal markings. You see owls, bears, wolves and stags carved into the surface.\n\nYou note a strange collection of symbols that makes your mouth form the word A-K-I-D-A.", objectives = "Read the Stillpine Furbolg Language Primer that Aurren gave you and interact with the Totem of Akida at Azure Watch.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9539] = { id = 9539, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Totem of Coo", description = "You begin to read the totem, barely able to pronounce the awkward words and phrases. Slowly, words start to form in your head. You think that the totem is telling you to go up the nearby hill, to the northeast.", completion = "The totem has various primal markings. You see owls, bears, wolves and stags carved into the surface of the totem.\n\nYou note a strange collection of symbols that makes your mouth form the word C-O-O.", objectives = "Find the Totem of Coo using the clues provided to you.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9540] = { id = 9540, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Totem of Tikti", description = "You begin to read the totem, better able to pronounce the words and phrases. Words start to form in your head. You think that the totem is telling you to go across the Crystalbrook river to the east. Perhaps your destination is on the other side of the river.", completion = "The totem has various primal markings. You see owls, bears, wolves and stags carved into the surface of the totem.\n\nYou note a strange collection of symbols that makes your mouth form the word T-I-K-T-I.", objectives = "Find the Totem of Tikti using the clues provided to you.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9541] = { id = 9541, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Totem of Yor", description = "The symbols on this totem seem to translate much faster. The patterns and imagery all seem to blend into familiar words. You are fairly certain the totem is pointing you south, down the river. Something is at the bottom of the river itself.", completion = "The totem has various primal markings. You see owls, bears, wolves and stags carved into the surface of the totem.\n\nYou note a strange collection of symbols that makes your mouth form the word Y-O-R.", objectives = "Find the Totem of Yor using the clues provided to you.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9542] = { id = 9542, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Totem of Vark", description = "You no longer see unrecognizable symbology in the totems. The totem of Yor reads to you just as easily as your native tongue.\n\nThe markings identify another furbolg den, due west of here. You are able to expertly decipher the language on the totem and know that your destination is Bristlelimb Village. Yor will guide you but if you get lost, you know that you are able to take the ancient elven road in the forest leading west to reach your destination.", completion = "As you read the totem, your mouth forms the word V-A-R-K. You understand this to mean justice.", objectives = "Find the Totem of Vark using the clues provided to you.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9543] = { id = 9543, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Atonement", description = "Our history with the orcs is one of constant conflict, {name}.  We were once near driven to extinction due to their bloodlust and have since then avoided them even when not under demonic influence.\n\nYet, this retaliation... it's not what Sedai would've wanted.  Speak with our elder, Amaan the Wise.  He will help shed light on these events.", completion = "Can I offer you any assistance, {name}?  You sound troubled.", objectives = "Speak to Amaan the Wise at the Temple of Telhamat in Hellfire Peninsula.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9544] = { id = 9544, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Prophecy of Akida", description = "The images on this totem depict a war between the Stillpine and the Bristlelimb furbolg tribes. The etchings show that the Bristlelimb have done unconscionable things to the furbolgs of Stillpine.\n\nAmidst the chaos, a prophecy has begun to unfold: A hero will rise - not of furbolg blood - and save the Stillpine tribe.\n\nSlay Bristlelimb furbolgs at Bristlelimb Village for their keys. Use the keys to free the Stillpine captives. Return to Arugoo of the Stillpine when you have freed them all!", completion = "[Furbolg] The prophecy spoke of one that would rise and deliver us from the oppressive grasp of Bristlelimb -- that the spirits themselves would herald the arrival of this hero.\n\nAnd now, you have come.\n\nI humble myself before you, great one.", objectives = "Free 8 Stillpine Captives from cages found in Bristlelimb Village. Return to Arugoo of the Stillpine at Azure Watch when you have completed this task.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9545] = { id = 9545, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Seer's Relic", description = "The stubborn close their mind and convince themselves of one truth.  The wise keep an open mind to the different possibilities leading to and stemming from the present.\n\nTake this relic with you to where you found Sedai.  See not with your eyes, {name}, but with your mind.", progress = "Have you seen the vision yet, {name}?", completion = "I hope the vision you witnessed helped you gain some perspective on Sedai's death.  The relic showed you a likely series of events leading up to the present.  The truth may have been different, we'll never know for sure.\n\nWould you act differently knowing what you know now?\n\nWho can say whether our conflict with the orcs will continue?  What's important is to remain open to the possibilities.", objectives = "Amaan the Wise at the Temple of Telhamat in Hellfire Peninsula wants you to return to Sedai's Corpse, northeast of the Temple of Telhamat, and use the Seer's Relic at that location. Return to him after you've completed this task.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9546] = { id = 9546, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fulfilling a Promise", description = "The prophecy spoke of one that would rise and deliver us from the oppressive grasp of Bristlelimb -- that the spirits themselves would herald the arrival of this hero.\n\nAnd now, you have come.\n\nI humble myself before you, great one. I beg of you, save our younglings. They were taken by the Bristlelimb while our guard was down. You will find them in cages at Bristlelimb Village, to the southwest. The Bristlelimb furbolgs hold the keys to the cages. Strike them down and take their keys. Release my kin.", objectives = "Arugoo of the Stillpine has asked that you free 8 Stillpine Captives from cages found in Bristlelimb Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9547] = { id = 9547, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call of Air", description = "{name}, Farseer Nobundo has been asking for you.  It must be time for you to learn the secrets of air, the last of the elements!\n\nI want you to know that I'm very proud of all that you have accomplished thus far.  I know that you have great things ahead of you.", completion = "And finally we come to it, the last of the four great elements: air. Do you think yourself wise enough to continue, {name}?", objectives = "Speak with Farseer Nobundo at the Crystal Hall inside the Exodar on Azuremyst Isle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9548] = { id = 9548, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pilfered Equipment", description = "Shh! Keep your voice down and don't call attention to me.\n\nIf the murlocs detect my presence, the experiment will be ruined! I've already come perilously close to contaminating my data.\n\nWhile I was foraging yesterday, one of them must've wandered too close and discovered my camp. I returned just in time to see two of them carrying off a crate with most of my equipment! It's bound to be in one of their settlements around here, but I can't risk revealing my presence. Are you willing to help?", progress = "Did you manage to find my equipment?", completion = "This is fantastic! The theft of my equipment has given me more insight into the nature of these murlocs than I could have possibly gained in weeks of observations!\n\nI know what I'm going to say in my report already.\n\n'When faced with the products of a technologically superior culture, the Blacksilt displayed none of the curiosity characteristic of emerging cultures in humanoid species.'\n\nIt's brilliant! The gentlemen in Ironforge are going to love it! I can't thank you enough, {name}.", objectives = "Bring Clopper's Equipment back to Clopper Wizbang, who is hiding in a beached turtle shell.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9549] = { id = 9549, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Artifacts of the Blacksilt", description = "My observations and writings about the Blacksilt murlocs are quite illuminating, {name}, but they are just the beginning. I plan to return to Ironforge with items produced by the Blacksilts' rudimentary crafting skills.\n\nThe problem is that the Blacksilt carry these items with them at all times, and I can't have their blood on my conscience. If you're willing to help me gather the idols carried by Blacksilt seers and crude knives of the Blacksilt warriors and shorestrikers, I won't ask how you came by them.", progress = "Do you have those samples for me to send back to Ironforge?", completion = "Astounding, simply astounding! These are perfect, {name}. I can already see them under the glass in the museum in Ironforge. The text for the display is virtually writing itself in my head!\n\nYour help has been invaluable in getting my studies back on track. How do you spell your name? I'll make sure it appears in my report as co-author.\n\nOne of the chaps on the ship gave me this 'treasure map' to cover a gambling debt, but mythology isn't my area of study. Superstitious lot, sailors.", objectives = "Bring 3 Crude Murloc Idols and 6 Crude Murloc Knives to Clopper Wizbang, who is hiding in a beached turtle shell.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9550] = { id = 9550, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Map to Where?", description = "The crudely-drawn map reveals nothing of its maker, but it appears to have been drawn with an unsteady hand. Wavering lines and symbols depict a small pavilion with broken columns located to the west of a partially submerged tower. \n\nIf the map is to be believed, this cluster of ruins appears to be located on the eastern coast of the island. You have no idea what you'll find, but it was important enough for the map's creator to record.", progress = "Perhaps this old journal is what the map is referencing.", completion = "Examining the book carefully, you conclude that it must be a journal. Its pages are filled with an elegant script differing from that of the map. The text of many of the pages is obscured by drawings and writing in the mapmaker's hand.\n\nIt's nearly impossible to make out the text beneath the mapmaker's tales of drunken carousing during shore leave.", objectives = "Locate the pavilion described by the map and search for what the map's maker was trying to record.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9551] = { id = 9551, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call of Air", description = "{name}, Farseer Nobundo has been asking for you.  It must be time for you to learn the secrets of air, the last of the elements!\n\nI want you to know that I'm very proud of all that you have accomplished thus far.  I know that you have great things ahead of you.", sourceObjective = "Speak with Farseer Nobundo at the Crystal Hall inside the Exodar on Azuremyst Isle.{name}, Farseer Nobundo has been asking for you. It must be time for you to learn the secrets of air, the last of the elements!\n\nI want you to know that I'm very proud of all that you have accomplished thus far. I know that you have great things ahead of you.", sourceObjectiveStatus = "unverified-source-field" }
quests[9552] = { id = 9552, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call of Air", description = "The great spirit of air calls out to you, {name}, and it is time for you to take heed.\n\nI wish for you to travel up the Wildwind Path on the north facing of the mountain that the Exodar has crashed into.  At its peak you will find a cave and within will be one of my most accomplished pupils, Velaada.\n\nPlease, listen to her wisdom and do as she bids.  When you return you will have a greater understanding of the element of air.", sourceObjective = "Speak with Velaada at Wildwind Peak on Azuremyst Isle.The great spirit of air calls out to you, {name}, and it is time for you to take heed.\n\nI wish for you to travel up the Wildwind Path on the north facing of the mountain that the Exodar has crashed into. At its peak you will find a cave and within will be one of my most accomplished pupils, Velaada.\n\nPlease, listen to her wisdom and do as she bids. When you return you will have a greater understanding of the element of air.", sourceObjectiveStatus = "unverified-source-field" }
quests[9553] = { id = 9553, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call of Air", description = "While air may seem ethereal, it is an all pervasive force, covering and permeating everything around us.\n\nThough you cannot see it, the rocks of this cave are composed mostly of air, the waters of the oceans are saturated in it and without it, fire cannot be sustained.  Just don't let those elements hear you repeat that!\n\nWho you really wish to speak with for such wisdom is nearby.  At the northern edge of the precipice, Susurrus awaits you.  It is from him that you will gain understanding.", sourceObjective = "Speak with Susurrus at Wildwind Peak on Azuremyst Isle.While air may seem ethereal, it is an all pervasive force, covering and permeating everything around us.\n\nThough you cannot see it, the rocks of this cave are composed mostly of air, the waters of the oceans are saturated in it and without it, fire cannot be sustained. Just don't let those elements hear you repeat that!\n\nWho you really wish to speak with for such wisdom is nearby. At the northern edge of the precipice, Susurrus awaits you. It is from him that you will gain understanding.", sourceObjectiveStatus = "unverified-source-field" }
quests[9554] = { id = 9554, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call of Air", description = "While my brothers and sisters of the other elements have demanded that you perform various tasks, I will not ask anything further of you.  I think that you have done enough to 'atone' for the accident of your ship falling to this place from my skies.  I can see that you have all the wisdom within you already to use the element of air wisely.\n\nTake this portion of my being back to Farseer Nobundo so that he might help you fashion your totem.  And when you're ready, I will fly you back down to the Exodar.", objectives = "Return to Farseer Nobundo at the Exodar on Azuremyst Isle with the Whorl of Air.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9555] = { id = 9555, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call of Fire", description = "I am thankful that you have chosen the difficult path of the shaman. Few enough do, but I foresee it as critical to our future that we learn shamanism from the Broken.\n\nThey are called that, but once they were draenei. Fel magics transformed them, and that is why they cannot call upon the power of the Light. Some disapprove of them and the shamanism they teach, but they are not evil.\n\nI wish you to speak with Farseer Nobundo. He is the wisest shaman I know and you will learn much with his guidance.You will learn:", sourceObjective = "Speak with Farseer Nobundo at the Crystal Hall in the Exodar.", sourceObjectiveStatus = "unverified-source-field" }
quests[9556] = { id = 9556, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To The Victor...", description = "You've no doubt been fighting long and hard among the towers, {race}. We would like to give something back to you in return for your defense of these lands, but first, you must prove to us you understand the weight of the tragedies that took place here.\n\nWalk the streets of Stratholme and find a vial of the holy water. Once you have it, travel to the mage quarter of Stormwind or the Undercity... There, if you are victorious within these lands, you will find my colleague.", objectives = "Collect a bottle of Stratholme Holy Water from within the city of Stratholme and deliver it to the Lordaeron Mage within the Mage Quarter of Stormwind or the Undercity when your side is victorious in the Eastern Plaguelands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9557] = { id = 9557, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deciphering the Book", description = "Lacking the means to read the book's contents, you think about who might be able to help you separate the author's words from the mapmaker's scrawl.\n\nRemembering Anchorite Paetheus's collection of artifacts from countless cultures, you wonder if his experienced eye might be able to help you decipher the book's contents.", progress = "The Light shine upon you in all your endeavors, {class}. What is it you have there?", completion = "Hmm... this is most intriguing. Yes, I should be able to make out what the original author wrote in the pages of this book.\n\nI should have everything I need for the process. This should only take a moment.", objectives = "Take the Ancient Journal to Anchorite Paetheus in Blood Watch.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9558] = { id = 9558, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Longbeards", description = "We were having a problem with arakkoa bandits raiding many of our supply caravans, so I hired some dwarves to take care of them.\n\nThey were brothers; Gremni Longbeard was the oldest.\n\nI'm a little worried about them.  Those crazy dwarves packed more ale than food or ammunition!  Maybe you can go check up on them?\n\nThe arakkoa's hideout, the Den of Haal'esh, can be found to the far west of here - beyond the Great Fissure.  They set up camp northwest of there, south of Dustquill Ravine.", completion = "How'd you find us, {class}?  No matter, I imagine you were sent here to give us a hand.  Let's get to work then!", objectives = "Look for Gremni Longbeard northwest of the Den of Haal'esh, to the far west of Honor Hold in Hellfire Peninsula.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9559] = { id = 9559, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stillpine Hold", description = "Promised one, you must travel north to the home of my people - Stillpine Hold. It is there that you will face your most daunting challenge.\n\nGo now, High Chief Stillpine awaits your arrival.", completion = "For centuries, we lived in relative peace with the creatures of the land. Several months ago, Kurz began to see dark omens. The peace that we enjoyed for so long was to be lost. The extent of the catastrophe could not be known!\n\nSo it would be that the gods would shatter our land - turning both friend and foe against us. But there was something else... Amidst the chaos, a hero would rise: A hero not of Stillpine blood. The Promised One would deliver us from devastation.\n\nThat prophesied hero was you.", objectives = "Speak with High Chief Stillpine at Stillpine Hold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9560] = { id = 9560, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beasts of the Apocalypse!", description = "My brother and I were hunting in the woods to the east when we were ambushed by strange, insect-like beasts. Such aberrations have never before been seen in Azuremyst! Could they be a sign of the coming apocalypse? The apocalypse that YOU are destined to prevent?\n\nIf you truly are the Promised One, you will strike the creatures of the apocalypse down... and bring me their hides. From their hides, I can fashion armor of great power!\n\nFind them to the east, beyond the road.", progress = "They are ugly little creatures. Even the Blind Watcher could see them... and he's blind.", completion = "Not only is the prophecy true, this armor is also amazing! Surely it is armor fit for a champion! And I will sell it to you at discounted prices, furless one.\n\nI jest... The first piece is complimentary.", objectives = "Moordo at Stillpine Hold on Azuremyst Isle wants you to bring him 8 Ravager Hides.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9561] = { id = 9561, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nolkai's Words", description = "The translation is ready now, {name}.\n\n<Anchorite Paetheus points out a block of text at the end of his translation.>\n\n'The enemy is nearly upon us. We've gathered up all the survivors and retreated to the temple to the east. It's the last ground we truly hold on the island, and there is a sense among the survivors that we will make our last stand here. I've taken care to bury my last few possessions on the grounds of the temple, with the hope that someone will find them and know what happened here.'", completion = "Grasses and shrubs cover an unnatural bulge in the earth.\n\nA few minutes spent digging reveals an old box, almost certainly the one mentioned in Nolkai's journal.", objectives = "Find the location described in Nolkai's journal and discover his long-buried possessions.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9562] = { id = 9562, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Murlocs... Why Here? Why Now?", description = "These are dark days, Promised One. Even the murlocs are kicking our tails - literally. Unfortunately, more than just my ego has been bruised.\n\nWhile our relationship with the Siltfin murlocs had always been tenuous, never could we have imagined that they would have the gall to attack us and steal from our food stores! Travel west to the Silting Shore and recover our stolen food-stuffs!\n\nAnd if you see a dark-skinned murloc with a patch of white fur stuck in between his webbed toes...", progress = "A murloc kicked me in the behind and spit on me... in broad daylight!", completion = "Mmmmm... Delicious grain... Parkat will be delighted!", objectives = "Gurf at Stillpine Hold on Azuremyst Isle wants you to recover 5 sacks of Stillpine Grain.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9563] = { id = 9563, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gaining Mirren's Trust", description = "So you want to gain our trust?  I don't trust many people these days.\n\nWe lost one of our own not long ago to the arakkoa.  It's got me a bit on edge.\n\nTell you what, if you can prove your loyalty to Honor Hold and... bring me a mug of Nethergarde Bitter... yes, that sounds rather good about now... I'll have a deal to offer you then.\n\nBernie at Nethergarde Keep keeps the bitter in stock.", progress = "Having trouble finding the bitter?  Good old Bernie at Nethergarde Keep should stock barrels of it.\n\nUnless he's run out... that would be disastrous!", completion = "Why, yes!  You seem to be quite an OK {race}.  I suppose I can trust you.", objectives = "Mirren Longbeard wants you to bring him 1 Nethergarde Bitter. You must also attain Friendly reputation with Honor Hold to complete this quest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9564] = { id = 9564, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gurf's Dignity", description = "You recover the piece of fur that Gurf had \"lost\" in his struggle with the murlocs. Return the fur to Gurf and let him know that the fearsome Murgurgula has been slain.", progress = "Is that what I think it is?", completion = "<Gurf spits on the clump of fur and tries to affix it to the hairless patch on his backside.>\n\nThis will have to do for now! Hopefully one of the shaman will be able to repair the damage.", objectives = "Return Gurf's Dignity to Gurf at Stillpine Hold on Azuremyst Isle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9565] = { id = 9565, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Search Stillpine Hold", description = "As High Chief, my immediate concern is the root of the corruption in Stillpine Hold.\n\nWhy did the wildkin - once our allies - attack us? Why have they taken residence in Stillpine Hold?\n\nPerhaps something inside will hold the answer. Search Stillpine Hold for clues as to the source of corruption.", completion = "The blood crystal radiates a sickly aura that seeps into the water of the cave.", objectives = "Search Stillpine Hold for clues.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9566] = { id = 9566, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blood Crystals", description = "On the surface, the crystal appears to be a piece of the Exodar. Something has gone terribly wrong with this crystal, however, as it is blood red and rapidly dissolving into the water supply of the cave.\n\nThis may explain the unusually aggressive behavior of the creatures in Azuremyst. Return to High Chief Stillpine with this information.", completion = "These blood crystals that you saw; my scouts have seen many more to the north.\n\nI thank you for aid but now ask that you leave me to confer with the elders. I will call for you once I have spoken with the other elders of the village.", objectives = "Speak with High Chief Stillpine at Stillpine Hold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9567] = { id = 9567, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Know Thine Enemy", description = "It's good to see another new face here in Blood Watch, {class}. Although the blood elves are the most immediate threat, there are other sinister creatures that call Bloodmyst Isle home.\n\nThe Nazzivus satyr are of particular concern. They are foul, demonic creatures, commanding dark magics and feeding on the corruption created by the Exodar's crash.\n\nWe must hold them in check, but first we must learn more about them. Go southwest to Nazzivian and learn what you can from their grotesque monument.", progress = "Were you successful in obtaining knowledge of the Nazzivus satyr?", completion = "Well done, {name}. Let me see what I can learn from this glyph, so we can plan our next move.", objectives = "Find the Nazzivus Monument in Nazzivian and retrieve a Nazzivus Monument Glyph. Return to Vindicator Aalesia in Blood Watch when you have one of the glyphs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9568] = { id = 9568, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "On the Offensive", description = "It's worse than I had imagined, {name}. We draenei know well what comes of selling one's soul to the Burning Legion in return for promises of power and immortality.\n\nThe satyr on this island, the Nazzivus, are descendents of that first, twisted creature who allied with the Legion. I fear that they will find a way to use the power of the Exodar's crystals against us.\n\nYou've seen what they've done to the land. Imagine what the satyr could do with them. Go southwest to Nazzivian and begin our offensive!", objectives = "Vindicator Aalesia at Blood Watch wants you to kill 10 Nazzivus Satyr, 5 Nazzivus Rogues, and 5 Nazzivus Felsworn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9569] = { id = 9569, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Containing the Threat", description = "Now that we have made our presence known to the satyr, we must send a message that we will not tolerate the Burning Legion's hounds in these lands.\n\nToo long have the draenei fled in the wake of the Legion and its minions, {name}. Wherever they have found us, they have shown no mercy.\n\nWe must not permit the satyr to exploit the Exodar's crash and use the corrupted crystals as weapons. Go north to where their leader resides in Axxarien, destroy him, and recover the corrupted crystals he has been gathering!", progress = "<Vindicator Aalesia seems to look through you rather than at you, her mind fixed on dealing with the satyr.>\n\nHave you moved against the satyr leader as I have asked?", completion = "Without their leader, and with the recovery of the corrupted crystals underway, we can safely keep the satyr in check. Light knows how many more of these wretched creatures are out there.\n\nHarbinger Mikolaas and I are grateful for the help you've provided in dealing with the satyr before they could become a larger threat. Your work stands as a reminder that vigilance is the key to victory against the Legion and its minions.", objectives = "Kill 5 Axxarien Shadowstalkers, 5 Axxarien Hellcallers, and Zevrax, then gather 5 Corrupted Crystals and return to Vindicator Aalesia in Blood Watch.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9570] = { id = 9570, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Kurken is Lurkin'", description = "After the crystal storm had subsided, a beast of myth appeared in our village. Brought here by the invading wildkin, this beast, the Kurken, laid waste to our village. Many Stillpine were slain in defense of our lands by this fiend and many have since lost their lives attempting to subdue the beast.\n\nIn my visions, I have seen one defeat the Kurken. The one must be you, {name}. You are our only hope. Enter Stillpine Hold and slay the Kurken. Bring me his hide as proof of deed.", progress = "<Kurz grunts at you.>", completion = "The Promised One has emerged victorious!\n\nThe prophecy is nearly complete. Now about that hide...", objectives = "Kurz the Revelator at Stillpine Hold on Azuremyst Isle wants you to kill the Kurken and bring back the Kurken's Hide.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9571] = { id = 9571, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Kurken's Hide", description = "Take the Kurken's hide to Moordo, on the other side of the village. He will fashion the hide into an item of your choice.", progress = "Hello, hero!", completion = "This is the strongest armor I've ever made! Make good use of it, {name}.", objectives = "Deliver the Kurken's Hide to Moordo at Stillpine Hold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9572] = { id = 9572, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weaken the Ramparts", description = "Quick, there isn't much time.  Thrallmar's existence balances on the razor's edge!\n\nWe're caught between Hellfire Citadel in the west and the Burning Legion to the east.  With the Legion's attention turned toward the Dark Portal we must take this opportunity to strike at the fel orcs of Hellfire Citadel.  The key to this is to first break through their ramparts!\n\nGo there, slay their leaders, and then bring back proof to Caza'rez across the room from me!", progress = "{name}, right?  Stok'ton told me to be expecting your report.\n\nI trust that you bring good news?", completion = "It's a good start.  With those three dead their forces should be in disarray.  And with their artillery up there silenced we'll have an easier time getting close enough to take the citadel!\n\nBut there's more to this than meets the eye - I can feel it - so I'm going to have something else for you to do.\n\nFor the time being, though, you've done well.  Take your pick of any of these from the Thrallmar armory.", objectives = "Slay Watchkeeper Gargolmar, Omor the Unscarred and the drake, Nazan. Return Gargolmar's Hand, Omor's Hoof and Nazan's Head to Caza'rez at Thrallmar in Hellfire Peninsula.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9573] = { id = 9573, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chieftain Oomooroo", description = "I am Stillpine the Younger, heir to the Stillpine legacy. As you can see, my defenders have set up a death trap for the raving wildkin that attack from inside Stillpine Hold. While we are able to hold them off out here, none of my defenders have been able to infiltrate the hold. If you could get inside and slay their leader, it might give us an opportunity to strike!\n\nFind Chieftain Oomooroo and destroy him. Slay any crazed wildkin that you encounter inside as well.", completion = "This may very well be the opportunity that we needed! I will send an attack at once! The Stillpine thank you for your service, {name}!", objectives = "Stillpine the Younger at Stillpine Hold on Azuremyst Isle wants you to slay Chieftain Oomooroo and 9 Crazed Wildkin.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9574] = { id = 9574, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Victims of Corruption", description = "Bloodmyst Isle was forever changed by our arrival. The Exodar's crash scattered debris all over the islands and I think it's beginning to have an adverse effect on the wildlife.\n\nBefore I can be certain of my conclusion, I'll need to get a closer look. The crystals seem to have affected the trees the fastest, so it seems that the treants would be the most likely to show symptoms. If you bring me samples of bark from corrupted treants, I can begin my in-depth studies.", progress = "Were you able to get the samples I need?", completion = "There's more than enough here for my research. Thank you, {name}. If you find any other evidence that the crystals are corrupting Bloodmyst's native creatures, let me know right away.", objectives = "Bring 6 pieces of Crystallized Bark to Morae in Blood Watch.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9575] = { id = 9575, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weaken the Ramparts", description = "Quick, {class}, there isn't much time.  Honor Hold's existence balances on the razor's edge!\n\nWe're caught between Hellfire Citadel in the west and the forces of the Burning Legion to the east.  With the Legion's attention turned toward the Dark Portal we must take this opportunity to strike at the fel orcs of Hellfire Citadel.  The key to this is to first break through their ramparts!\n\nGo there, slay their leaders, and then bring back proof to Gunny across the hall here from me!", progress = "{name}, right?  Chadwick told me to be expecting your report.\n\nWHAT are you doing in my presence?!  Is your assignment complete?  Are you a complete and utter lackwit?  You make me want to vomit!\n\nNow get your worthless hide up on those ramparts and do what you were instructed to do!  Do you hear me?!", completion = "Do you know what I hate worse than being wrong? Losing gold on a bet that you couldn't pull it off, sweetheart.\n\nOutstanding!  With those three dead their forces should be in disarray.  And with their artillery up there silenced we'll have an easier time getting close enough to take the citadel!\n\nI have a feeling there's more to this than meets the eye, though - so I'm going to have something else for you to do.  Here, take one of these from the armory.", objectives = "Slay Watchkeeper Gargolmar, Omor the Unscarred and the drake, Nazan. Return Gargolmar's Hand, Omor's Hoof and Nazan's Head to Gunny at Honor Hold in Hellfire Peninsula.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9576] = { id = 9576, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cruelfin's Necklace", description = "Examining the crudely constructed pendant, you notice the crystal pulsating softly. Though it emits little light, you can almost feel the crystal radiating a sense of wrongness.\n\nYou're not quite sure what might have possessed Cruelfin to create this pendant, but the find is too important to ignore. You should probably show it to someone at Blood Watch.", progress = "What is it you have there?", completion = "This is most curious, {class}. I don't believe we've ever seen the murlocs wearing any kind of adornment before.\n\nGiven the corrupting influence that the crystal shards are known to have, the murloc that wore this pendant must have believed it granted him power over his fellows. I wouldn't be surprised if he had rapidly outgrown his fellow murlocs and gained in strength.", objectives = "Bring the Red Crystal Pendant to Morae at Blood Watch.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9578] = { id = 9578, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Searching for Galaen", description = "Do you think often of your family, {name}? There were a number of families aboard the Exodar, but I've heard of very few being reunited.\n\nI, myself, am looking for traces of my husband Galaen, who was a technician in the Cryo-Core. The wreckage of it is located to the west, and it's swarming with blood elves!\n\nI must find out what became of Galaen! Even news of his death is better than never knowing. My husband will be wearing a pendant identical to my own; they were a gift from my sister.", completion = "The corpse appears to be dressed in the manner of an Exodar technician, but the pendant described by Morae is absent.", objectives = "Search for Morae's husband Galaen.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9579] = { id = 9579, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Galaen's Fate", description = "You have no means of identifying the corpse as Galaen with the information Morae gave you, but the clothing appears to have been torn in search of valuables.\n\nThe blood elves in the area would've claimed anything of value from the wreckage, including Galaen's jeweled amulet.\n\nAlthough her husband did not survive the crash, you believe that Morae would be grateful if you recovered her husband's amulet from the blood elves.", progress = "<Morae looks at you hopefully.>\n\nDid your search turn up any trace of Galaen?", completion = "<You tell Morae of your findings in the wreckage of the Cryo-Core.>\n\nSo... he's...\n\nI guess I knew on some level, but just wouldn't let myself believe it. It's not the news I was hoping for, but you have my deepest thanks for finding Galaen.", objectives = "Bring Galaen's Amulet to Morae at Blood Watch.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9580] = { id = 9580, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Bear Necessities", description = "As I'm sure you've seen in your time on Bloodmyst Isle, very little remains unchanged by our arrival. My training and experience has taught me that even the products of an environment like this one can be put to use.\n\nWith so few resources, we must rely on our ingenuity to provide for us. I've been supplementing our stores with meat from the bears that wander this island. With the proper preparation, it can safely be eaten. If you're going to be out in the field, why not help replenish our stocks?", progress = "How goes the hunt, {name}?", completion = "This will keep us supplied for quite a while, and preparing it for consumption will certainly keep me busy. Thank you for your help, {name}.", objectives = "Bring 8 Elder Brown Bear Flanks to Tracker Lyceon in Blood Watch.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9581] = { id = 9581, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Learning from the Crystals", description = "Welcome to Blood Watch, {class}. Seeing to the defenses of the outpost is my primary concern, but I've also been tasked with a variety of other duties by our leaders at the Exodar.\n\nThe problem is that it's hardly safe to send out large amounts of researchers when the island is this dangerous. I need someone to gather a series of crystal samples from various sites on the island.\n\nThe first sample I need must come from the ravager infested ship debris south of the town and across the bridge.", progress = "Were you able to gather the first crystal sample?", completion = "This crystal shard will give our researchers a baseline to compare against samples from other parts of the island, since it comes from one of Bloodmyst's less corrupted regions.\n\nI won't be able to send it off until we have a full set of samples, but this is a great start. If you're willing to help gather the other samples, I'll see to it that you're rewarded for your efforts.", objectives = "Get an Impact Site Crystal Sample using the Crystal Mining Pick on the Impact Site Crystal and bring it to Harbinger Mikolaas in Blood Watch.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9582] = { id = 9582, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Strength of One", description = "When the ship crashed, our menagerie was scattered on the northeast beaches of this isle.  I have been handed a key that unlocks the cage holding one of the deadlier specimens, a death ravager.  The creature is little armored but resistant to most magic.  It must be killed by a simple blade.\n\nTake this key and release the creature from both its prison and its pain.  We cannot afford to have it escape and cause even more damage to the ecology than we already have.", progress = "Have you put down the beast?", completion = "<Ruada nods solemnly.>\n\nThen it is done.\n\nYou are ready for your next lesson, {name}, but I will not be the one to teach it to you.", objectives = "Unlock the Ravager Cage and kill the Death Ravager, then return to Ruada at Azure Watch in Azuremyst.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9584] = { id = 9584, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Second Sample", description = "Now that we have the baseline crystal, we're going to need samples from more dangerous areas of the island to complete the set I'll be sending to the Exodar.\n\nThe next sample must come from the crystals controlled by the blood elves in the Bladewood area to the northwest of Blood Watch. I have heard reports that they alter and harvest the crystals for use in some magical apparatus. See if you can find one that has not yet been incorporated into one of their devices, and mine a sample from it.", progress = "Do you have the second crystal sample?", completion = "<Harbinger Mikolaas examines the crystal shard.>\n\nThis shard is much different from the initial sample.\n\n<Harbinger Mikolaas holds the crystal up to catch the light.>\n\nDo you see how it pulsates like that? That's worrisome. I'll make a note in my report of the alterations the blood elves appear to have made to this crystal. Thank you again for your help, {name}.", objectives = "Get an Altered Crystal Sample using the Crystal Mining Pick on the Altered Bloodmyst Crystal and bring it to Harbinger Mikolaas in Blood Watch.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9585] = { id = 9585, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Final Sample", description = "There's just one sample remaining before I can send this set of crystals to the Exodar, {name}. The final sample must come from the satyr stronghold of Axxarien to the northwest.\n\nI'm not certain what to expect from this crystal sample, but I'm sure there will be some signs of corruption. Take care to mine your shard from the crystal that looks like the ones you took your previous samples from, or else our researchers cannot make a valid comparison.", progress = "Have you returned with the last sample for my set?", completion = "<Harbinger Mikolaas accepts the last crystal from you.>\n\nThat rounds out the set. All that remains to be done is to box them and send them to the Exodar.\n\n<The harbinger seems glad to be done with the task.>\n\nDon't get me wrong, {name}, I'm sure the research is valuable, but we're faced with a number of other pressing problems out here.", objectives = "Get an Axxarien Crystal Sample using the Crystal Mining Pick on the Axxarien Crystal and bring it to Harbinger Mikolaas in Blood Watch.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9586] = { id = 9586, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Help Tavara", description = "Tavara, one of our herbalists, has been gone far too long in her search for herbs.  I fear she is hurt and in need of help, yet I cannot look for her myself.\n\nPlease find her and lend your healing if needed, fellow {class}.  She was heading east towards some hot springs when she left Azure Watch.", objectives = "Guvan at Azure Watch wants you to find Tavara and heal her wounds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9587] = { id = 9587, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dark Tidings", description = "Giving the lifeless form of Vazruden the Herald the once-over, you discover a rolled letter, its seal yet unbroken.  An elaborate \"I\" is pressed within the blood-red ink.  Cracking the note open, the message that you read is most disturbing.\n\nForce Commander Danath Trollbane back at Honor Hold will definitely want to take a look at this!", progress = "What's that you have there, son?", completion = "It's signed by Illidan you say?! Let me have that.\n\n<The commander reads the letter, and then again a second time, thinking a moment before going on.>\n\nThis news that you bring is ominous indeed. Knowing this, we must accelerate our plans against Hellfire Citadel and this Blood Furnace. Because you have shown that you can get the job done, I want you to head up those plans.\n\nGunny will give you your next mission, though I suspect it will be far deadlier than your first.\n\nLight be with you, {name}!", objectives = "Take the Ominous Letter to Force Commander Danath Trollbane at Honor Hold in Hellfire Peninsula.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9588] = { id = 9588, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dark Tidings", description = "Giving the lifeless form of Vazruden the Herald the once-over, you discover a rolled letter, its seal yet unbroken.  An elaborate \"I\" is pressed within the blood-red ink.  Cracking the note open, the message that you read is most disturbing.\n\nNazgrel back in Thrallmar will definitely want to take a look at this!", progress = "What is that letter you have there, {class}?", completion = "It's signed by Illidan you say?! Let me have that.\n\n<Nazgrel reads the letter, and then again a second time, thinking a moment before going on.>\n\nThis news that you bring is ominous indeed. Knowing this, we must accelerate our plans against Hellfire Citadel and this Blood Furnace. Because you have shown that you can get the job done, I want you to head up those plans!\n\nCenturion Caza'rez will give you your next mission, though I suspect it will be far deadlier than your first.\n\nLok'tar ogar, {name}!", objectives = "Take the Ominous Letter to Nazgrel at Thrallmar in Hellfire Peninsula.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9589] = { id = 9589, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Blood is Life", description = "That letter is going to get folks all riled up around here.  They'll think there's something we might do about all those new fel orcs being created if only we knew how it was being done.  It's bad enough that we have to fight the Burning Legion to the east.\n\nSo, it's your lucky day, sweetness!  You get to take a stroll into what they call the Blood Furnace inside Hellfire Citadel.  Sounds hot!\n\nGet in there, kill some fel orcs and bring back samples of their blood.\n\nYou think you can handle that?", progress = "You have that blood, darlin'?  Might be kind of important if we asked you to get it, you know?", completion = "Out-frikkin-standing!  As of right now Private {name}, you are my favorite person on the sorry remains of this sorry planet!\n\nI'm sure that the eggheads are going to wet themselves when I hand that blood over to them for study.  Who knows, maybe we'll find a new weapon in the fight against those damned fel orcs?", objectives = "Collect 10 Fel Orc Blood Vials and return them to Gunny at Honor Hold in Hellfire Peninsula.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9590] = { id = 9590, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Blood is Life", description = "That letter is disturbing, and not just because it comes from the Betrayer.  We must know how they are creating these new fel orcs if we're to defeat them!  It's bad enough that we must fight the Burning Legion on our eastern flank, but now a new army of fel orcs to the west!\n\nYou must infiltrate this Blood Furnace inside Hellfire Citadel.  Bring back samples of blood from the fel orcs that you find in there.", progress = "Surely you have not collected all of the blood so quickly?", completion = "I am impressed with your abilities, {name}.  Not once, but twice now you have infiltrated Hellfire Citadel for us and accomplished what was asked of you.\n\nI will see to it that this blood is delivered to those who can unlock its mysteries.  Who knows, perhaps we can find a way to reverse the process?", objectives = "Collect 10 Fel Orc Blood Vials and return them to Centurion Caza'rez at Thrallmar in Hellfire Peninsula.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9591] = { id = 9591, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taming the Beast", description = "When the {class} first begins <his/her> path, <he/she> learns only to kill.  Now it seems you are ready for more.\n\nThe Stillpine furbolgs have provided a means to master the skill of taming without months of study.  They are able to carve a totem into the likeness of an animal, which you can use to temporarily bond with a creature of that type.\n\nFor your first lesson, take this totem and use it on the barbed crawlers found along the western coast of the isle.", objectives = "Use the Taming Totem to befriend a Barbed Crawler and return to Huntress Kella Nightbow when you have succeeded.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9592] = { id = 9592, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taming the Beast", description = "The crawler was undoubtedly mean, but the timberstrider will test your resolve.  More powerful allies require more tenacity from the hunter.\n\nTake this taming totem and befriend a greater timberstrider.  They are found in the northern reaches of Azuremyst Isle.", objectives = "Use the Taming Totem to befriend a Greater Timberstrider and return to Huntress Kella Nightbow.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9593] = { id = 9593, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taming the Beast", description = "You probably noticed the big cats known as nightstalkers when you tamed the timberstrider.  They are efficient and deadly hunters... and allies.\n\nUse this taming totem to befriend a nightstalker.  Hunt with the vicious cat and keep it from harm.  When you are finished, return to me.You will learn:", objectives = "Use the Taming Totem to befriend a Nightstalker and return to Huntress Kella Nightbow.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9594] = { id = 9594, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Signs of the Legion", description = "The armor scrap is forged from a deep black metal that seems to absorb light. Although it doesn't appear to be enchanted, there is an unmistakable sense of wrongness about it.\n\nSuch armor is only used by one force - the Burning Legion. The Legion's presence here can only mean that they're intending to mobilize the island's satyr against the draenei.\n\nTake action against the local satyr, then return to Blood Watch and show this armor scrap to Vindicator Aalesia.", progress = "Yes, {class}? What is it you have there?", completion = "You've done well in bringing this to me, {name}. This is, without a doubt, an armor fragment from a felguard.\n\nThen, it is as I feared. The Nazzivus satyr are renewing their contacts with the Burning Legion. If we don't stop them, the satyrs and their demonic allies will overrun us. I will notify Harbinger Mikolaas right away.", objectives = "Kill 8 Nazzivus Satyr and 8 Nazzivus Felsworn, then bring Tzerak's Armor Plate to Vindicator Aalesia in Blood Watch.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9595] = { id = 9595, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Control", description = "You have chosen the path of the {class}, and so you must learn control. Magic, when unchecked, can corrupt souls and destroy worlds.\n\nTo fully understand, you must face one who has been consumed by magic. Travel to the beaches on the northwest coast of Azuremyst Isle and use your spells to decimate the murlocs. The display of power will attract the attention of the evil force lurking there, a Quel'dorei magewraith. Defeat it.\n\nWhen you have finished, seek out Bati at the Vault of Lights in the Exodar.", completion = "With every spell you must steel yourself against its seductive lure, using it only as needed for the purposes of good.  Hopefully the wraith granted a glimpse of what you might turn into should you become careless--a mindless slave to magic.", objectives = "Kill Murlocs of the Silting Shore to summon a Quel'dorei Magewraith, then destroy it. Afterwards, speak with Bati at the Vault of Lights in the Exodar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9598] = { id = 9598, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Redemption", description = "I am responsible for putting paladins on the path to greater virtue as they devote themselves to the Light and defend our people from threats.\n\nThe time has come for you to take your first step towards being truly virtuous. If you accept it, I will give you a tome of divinity. In studying it, you shall learn some about the Light, and what is expected of you. If you understand it, and are capable, then you will succeed in attaining greater abilities.", objectives = "Study the Tome of Divinity and speak with Jol.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9600] = { id = 9600, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Redemption", description = "Your task then, {name}, is to aid our new allies, the Stillpine furbolgs.\n\nSeveral of the younger Stillpine shaman stumbled across a Bristlelimb camp and were slaughtered to the last.  Take this Symbol of Life and resurrect one of the shaman.\n\nBristlelimb Enclave is located to the east of the road just after you cross the bridge spanning Azuremyst and Bloodmyst Isle.  Speak with me when you have done this.You will learn:", objectives = "Jol wants you to resurrect a Young Furbolg Shaman with the Symbol of Life and return to her.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9601] = { id = 9601, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To The Bulwark", description = "The blood knight Mehlar Dawnblade has requested an audience with you, {name}.  Mehlar can be found at the Bulwark, guarding the passage between Tirisfal Glades and the Western Plaguelands.\n\nHe is not known for his patience.  It would not be wise to keep him waiting.", sourceObjective = "Speak with Mehlar Dawnblade at the Bulwark.The blood knight Mehlar Dawnblade has requested an audience with you, {name}. Mehlar can be found at the Bulwark, guarding the passage between Tirisfal Glades and the Western Plaguelands.\n\nHe is not known for his patience. It would not be wise to keep him waiting.", sourceObjectiveStatus = "unverified-source-field" }
quests[9602] = { id = 9602, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deliver Them From Evil...", description = "You must get this information to your people, {name}. While your brave acts have certainly slowed down the plans of Kael'thas and his dark master, the attacks will undoubtedly continue.\n\nTake the traitor's communication to your leaders. They must see this for themselves. Perhaps they will be able to better understand some of what was written.", progress = "You have returned!", completion = "<Exarch Menelaous takes the letter from you and begins to read it.>\n\nDamn them... Damn them all to the Nether. They've had a spy watching everything that we've done! And for how long?\n\nI will notify Velen at once!\n\nYou've done us a great service, {name}. Be on guard as I will be contacting you once the Prophet has given me instruction as to what to do.", objectives = "Deliver the Traitor's Communication to Exarch Menelaous at Azure Watch.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9603] = { id = 9603, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beds, Bandages, and Beyond", description = "Welcome to Azure Watch, {class}. Please excuse the disorder you see around you. It's easy to take simple things for granted, like a fully furnished and stocked inn, until you're forced to build one from nothing.\n\nWe've managed to salvage this pod for a building, but without the proper furnishings and first aid supplies, the inn is little more than a glorified tent. Nurguni at the Exodar has offered to put together a package to help with our most immediate needs, but I need someone to deliver this list to him.", progress = "Good day, {name}. Are you interested in renting a hippogryph?", completion = "So you need to go to the Exodar?\n\nThat's going to be a bit of a trip, but don't worry, I have a way to get you there very quickly.", objectives = "Take Chellan's List to the hippogryph master Zaldaan at Azure Watch.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9604] = { id = 9604, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "On the Wings of a Hippogryph", description = "For a small fee, you can rent one of my hippogryphs to fly you to the Exodar.\n\nTaking the hippogryph is a faster, not to mention safer, alternative for someone carrying an important message. If you'd like to take a ride, speak to me again and I'll make the arrangements.", progress = "Greetings, friend. You look like you've come a long way. How can I help you?", completion = "So you've brought Chellan's list. Excellent! I was hoping to receive this today. Let's see what she needs.\n\n<Nurguni reads over the list and begins placing various items in a box.>\n\nThat's most of what she requested. The pieces for the beds are simply too large to be delivered by hippogryph, but I'll make arrangements to have them sent by wagon.", objectives = "Purchase a hippogryph ride to the Exodar from Zaldaan. When you land, take Chellan's List to Nurguni in the Seat of the Naaru at the Exodar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9605] = { id = 9605, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hippogryph Master Stephanos", description = "Here's the box, {name}. That should be enough for Chellan to get the inn up and running. Let her know that she can keep sending in orders as the need arises. Azure Watch urgently needs a place to care for the wounded and put up any travelers they receive.\n\nWhen you're ready to return to Azure Watch, seek out Stephanos near the Seat of the Naaru in the Exodar.", progress = "Where are you headed, {class}?", completion = "So you're headed back to Azure Watch with this package? No problem at all, {class}. Just speak with me again and we'll get you on your way with those supplies.", objectives = "Find Stephanos at the Seat of the Naaru inside the Exodar and purchase a hippogryph ride back to Azure Watch.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9606] = { id = 9606, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Caregiver Chellan", description = "If I remember correctly, Azure Watch's hippogryph master is Zaldaan.  If you've spoken to him before, then you can take one of my hippogryphs to him.\n\nThat's a good lesson to know: hippogryphs are always trained to fly to their capital city, but they'll only take you to a remote hippogryph master after you've already been there.\n\nSince you arrived on one of Zaldaan's hippogryphs, you can also use that route to return to Azure Watch with the caregiver's supplies.", progress = "Welcome back, {name}. Was Nurguni able to gather everything on the list?", completion = "<Handing over the box, you tell the caregive that Nurguni is making arrangements to have the larger items delivered by wagon.>\n\nSplendid! Now, I'll finally be able to set up some beds and a first aid station so that we can better treat the wounded and any survivors we encounter.\n\nI can't thank you enough for your help, {name}. You have my thanks and that of the Azure Watch's vindicators.", objectives = "Speak with Stephanos to purchase a hippogryph ride back to Azure Watch. Once you have arrived, deliver Nurguni's Supplies to Caregiver Chellan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9607] = { id = 9607, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heart of Rage", description = "{class}, put together a force to investigate the Blood Furnace inside Hellfire Citadel at once!  And that means today, princess!\n\nThe magic we have at our disposal indicates that something unnatural is occurring in there.  But something more powerful inside is blocking any detailed arcane investigations.  It figures!\n\nYou can expect heavy resistance - no other mission that we've sent in there has yet to return!\n\nScout it entirely and then report back to the force commander with what you witness.", completion = "THEY HAVE A PIT LORD?!\n\n<The force commander looks around at the stares of the others and then lowers his voice to a whisper.>\n\nThat seals it.  They must be using the blood from this pit lord to create new fel orcs that are somehow not aligned with the Burning Legion.  And if they can do this to the brown orcs, they can do it to the green ones too.  With all of the new Horde orcs streaming in through the Dark Portal, that's not good!\n\nWe must strike at the heart of their military might, and soon!", objectives = "Fully investigate the Blood Furnace and then report to Force Commander Danath Trollbane at Honor Hold in Hellfire Peninsula.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9608] = { id = 9608, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heart of Rage", description = "{class}, you must gather a group to investigate the Blood Furnace inside Hellfire Citadel at once!\n\nThe magical scrying that we have at our disposal indicates that something unnatural is occurring in there.  But a powerful force inside is blocking any detailed arcane investigations, so it must be very important.\n\nYou should expect heavy resistance - no other mission that we've sent in there has ever returned!\n\nScout it entirely and then report back to Nazgrel, advisor to Thrall, with what you witness.", completion = "THEY HAVE A PIT LORD?!\n\n<Nazgrel notices the glances of the others assembled and lowers his voice to a whisper.>\n\nThat seals it.  They must be using the blood from this pit lord to create new fel orcs that are somehow not aligned with the Burning Legion.  And if they can do this to the Mag'har brown orcs, they can do it to us!\n\nWe'll have to strike at the heart of their military might, and soon!", objectives = "Fully investigate the Blood Furnace and then report to Nazgrel at Thrallmar in Hellfire Peninsula.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9609] = { id = 9609, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "elp Watcher Biggs", description = "Magtoor has informed me that there's a stranded watcher nearby.  Apparently the caravan he was escorting from Darkshire was attacked by Lost Ones.  It sounds as if he's the sole survivor.\n\nHe's somewhere to the south.  Please, {class}, lend him your aid.", completion = "What?  A draenei sent you here from the Harborage?  How odd.\n\nWell, I'm not one to turn down assistance.  Thanks for coming, {class}!", objectives = "Find Watcher Biggs in the Swamp of Sorrows.Magtoor has informed me that there's a stranded watcher nearby. Apparently the caravan he was escorting from Darkshire was attacked by Lost Ones. It sounds as if he's the sole survivor.\n\nHe's somewhere to the south. Please, {class}, lend him your aid.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9610] = { id = 9610, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "ool of Tears", description = "I am interested in studying Azeroth's past and I'm wondering if you'd be willing to help?\n\nThere is a nearby place of historical significance within the swamp that I would like for you to venture to.  The Pool of Tears lies to the southeast.  It is said that upon its shores and within its depths are buried artifacts of the Atal'ai troll civilization.\n\nBut beware, it is guarded by Somnus, an ancient green dragon, and his dragonkin, as well as carnivorous fish in the pool itself!", progress = "I look forward to you gathering enough of the Atal'ai artifacts so that I might begin to study them.  I'm eager to discover what happened to their once-great civilization.", completion = "I thank you, {class}.  The study of these artifacts should keep me occupied for some time.  How else are we Broken and {race} to fit in if we do not come to understand the history of your world?", objectives = "Obtain 5 Atal'ai Artifacts and return them to Holaaru at the Harborage in the Swamp of Sorrows.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9611] = { id = 9611, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Azuremyst: aa - A - Quest Flag 000" }
quests[9612] = { id = 9612, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Hearty Thanks!", description = "You saved my life, {name}! Thank you so much! That beast would have torn me to shreds if it weren't for you.\n\nIf you see the exarch at Azure Watch, tell him of what you did. I'm sure he'll be pleased to hear such news!", completion = "Well done, {name}. Well done indeed! You are turning out to be a special {race} - a cut above the others of your age. Take this as a reward!", objectives = "Speak with Exarch Menelaous at Azure Watch.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9616] = { id = 9616, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bandits!", description = "This appears to be a bounty ledger. You cannot understand the blood elf language but you note that there is a picture depicting a dead draenei, a smiling blood elf standing over the corpse, and a symbol of what you think is some sort of blood elf currency.\n\nThey've put a hit out on draenei! You must inform the exarch.", progress = "Yes? I'm very busy, {name}.", completion = "By the beardless, geometric head of O'ros! It is good you brought this to me, {name}. These blood elves are out for... well, blood. Velen will be informed at once! Take this as a reward.", objectives = "Take the Blood Elf Communication to Exarch Menelaous at Azure Watch.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9617] = { id = 9617, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seek the Farstriders", description = "Lieutenant Dawnrunner at Farstrider Retreat has requested an audience with all able hunters.  It would greatly benefit you to seek her out, {name}.  She is a beacon of wisdom for those of our calling.\n\nFarstrider Retreat lies south of Silvermoon City.", completion = "{name}, it is good you have come.  Our list of allies grows thin, and even those who share our cause are not completely trusted.  It is because of this that we, the rangers, turn to nature for aid.\n\nIn the allies of the forest we find a deep bond that does not know deceit.", objectives = "Speak with Lieutenant Dawnrunner at Farstrider Retreat.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9618] = { id = 9618, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return the Reports", description = "Your sleight of hand was most impressive.  There's no question that I can trust you to take these reports to Zelanis.", objectives = "Bring Keltus Darkleaf's Reports to Zelanis in Silvermoon City.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9619] = { id = 9619, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Rune of Summoning", description = "The voidstone reveals a vision of a multi-story building haunted by ghostly figures.  As the scene sharpens and blurs, other buildings come into view, leading you to believe it is Goldenmist Village.\n\nRooftops and tree canopies suddenly flash by, revealing the way to Goldenmist by following the Elrendar River to the west.\n\nOnce there, use the voidstone near the rune of summoning atop the center building and defeat the summoned voidwalker.  Only then can you return to your teacher.", progress = "Have you followed the path revealed by the voidstone?", completion = "I'm impressed you are standing here, {name}.  Many an apprentice has perished to the voidwalker, or even the voidstone itself.\n\nThe voidwalker is now yours to command.  Use your new servant well.", objectives = "Use the Voidstone to summon a Voidwalker in Goldenmist Village, defeat it, and return to Talionia in Silvermoon City.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9620] = { id = 9620, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Missing Survey Team", description = "As we've gotten ourselves established here at Blood Watch, I've been sending out survey teams to create more reliable maps of the island. In most cases, they returned unharmed with the data we need, but the team I sent east to the ruins hasn't reported back.\n\nI worry about what might have happened to them, but I can't spare the men to send another mission after them. Find them, {name}, and lend them any assistance they require to return with their survey data.", completion = "The bodies of the draenei survey team are scattered all over the ground here, pierced by naga weaponry. The area is littered with the remains of their supplies and survey equipment, but their data crystals are nowhere to be seen.", objectives = "Harbinger Mikolaas wants you to find the Survey Team he sent to the Ruins of Loreth'Aran and assist them in any way you can.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9621] = { id = 9621, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Envoy to the Horde", description = "There were doubts about our capabilities among our potential new allies.  Of what use could we be to them when perceived as unable to deal with our problems at home?\n\nThis changes everything.  No longer will our power be questioned.  We'll be able to join the Horde as equals.\n\nTake this letter to Sylvanas, ruler of the Forsaken.  She's already on our side but the news of Dar'Khan's death will be music to her ears.  Prepare for a long trip, {name}.  If all goes well she will send you to Orgrimmar.", progress = "Ah, a visitor from Quel'Thalas!  What news do you bring?", completion = "It is done then.  The foul traitor got what he deserved.\n\nYou did this yourself?  An impressive feat that proves that your race remains worthy, {name}.\n\nI see that Lor'themar has additional news that will greatly improve his relations with the trolls and their Warchief.", objectives = "Bring the Letter from Lor'themar Theron to Lady Sylvanas Windrunner in Undercity, the Forsaken capital in Tirisfal Glades.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9622] = { id = 9622, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warn Your People", description = "The Hold is saved and soon my people will make their way back to the ancestral home. The prophecy has come to pass and a new age of prosperity begins for the Stillpine.\n\nBut I fear that darkness looms ahead for your own people. There are questions left unanswered - visions of prophecy unseen.\n\nReturn to your leaders and tell them of what you have seen here.\n\nAnd Promised One, should you ever require the aid of Stillpine, you have merely to ask.", completion = "Visions you say? Interesting... And this prophecy has come to pass?\n\nBut you say they saw the power core of the Exodar? And O'ros was also in the vision? What can it mean?", objectives = "Speak with Exarch Menelaous at Azure Watch.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9623] = { id = 9623, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Coming of Age", description = "You have survived the wilds of our new home and shown yourself a cut above the others. I believe that you have come of age to assist those battling on the front lines of Bloodmyst. The Hand of Argus could use a {race} like you. \n\nReport to Torallius the Pack Handler. You will find him outside the Exodar, tending to the elekk. Give him these orders so that he may direct you towards your new duties on Bloodmyst.", progress = "<Torallius adjusts his eyepatch to look at you.>\n\nThis is the best we can offer the Hand of Argus?", completion = "<Torallius sighs.>\n\nAlright, let me have a look at those orders.", objectives = "Exarch Menelaous at Azure Watch has asked that you deliver the Exarch's Orders to Torallius the Pack Handler, standing outside of the Exodar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9624] = { id = 9624, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Favorite Treat", description = "I've made a wonderful discovery, {class}. On the uncorrupted part of the island grows a remarkable fruit called the sand pear. They're found near the bottoms of the trees.\n\nI've been preparing pies from them, but if I'm not careful, the elekk will start to wander over and steal my fruit. I've taken to gathering enough to share with the animals, but my stores are gone and the craving for pie has returned. Would you be willing to help gather the fruit I need for another batch of pies? I promise I'll share!", progress = "The sand pears are getting harder to find and, of course, that means less pie and fewer treats for the elekk here. Were you able to gather all the fruit I'll need?", completion = "Did you have a difficult time finding enough? It's been taking me longer with each trip.\n\nSoon, I'll have to stop altogether since I won't be able to spare the time. Thank you for gathering the pears for me, {name}. It gives me a chance to make a last pie or two before the season's out.", objectives = "Aonar at Kessel's Crossing wants you to bring him 10 Sand Pears.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9625] = { id = 9625, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elekks Are Serious Business", description = "Is he crazy? Entrusting something like this to some no-named {race} youngling!\n\nJust remember this kid: You'll never make it as a Hand of Argus! You don't have the guts!\n\nI guess I'll have to humor him this time. Speak with Vorkhan at Kessel's Crossing on Bloodmyst Isle. Just follow the road north from here, and when it forks, just keep on going north.", completion = "Well ya made it this far! Let's put ya to work before you get too bloodied up.", objectives = "Speak with Vorkhan the Elekk Herder on Bloodmyst Isle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9626] = { id = 9626, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meeting the Orcs", description = "I haven't lost any love for my homeland or its people, as you know. I've fought tooth and nail for Silvermoon to be allowed a place beside Undercity and Orgrimmar at the negotiating table.\n\nThis should silence any opposition. Take this letter to Saurfang in Orgrimmar. As leader of the orcs, he must have a say in accepting the sin'dorei's pledge.\n\nI've added my own seal to the letter as a personal endorsement. Go northwest of the city and board the zeppelin bound for Durotar at the tower.", progress = "You've come to see me, {race}?  Speak and be quick, young lady.  I've no time for the formalities of your race.", completion = "<The Warchief begins to read the letter.>\n\nSylvanas is a persistent one.  So she's sent one of Silvermoon's own champions... how does this change anything?", objectives = "Lady Sylvanas Windrunner wants you to take the Letter Sealed by Sylvanas to High Overlord Saurfang in Orgrimmar, capital of Durotar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9627] = { id = 9627, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Allegiance to the Horde", description = "Your people suffered a great betrayal by the Alliance. You succeeded in fighting off the Darnassian attacks and the spies from Ironforge. Now you defeated a powerful Scourge leader at the footsteps of your home. Your worthiness is no longer in question.\n\nIt is clear now that we need each other. Return to Lor'themar. Tell him I have heard your message and accept. \n\n<Saurfang crushes the letter inside his palm.> \n\nWelcome to the Horde, elf.", completion = "Your work has helped advance our race's cause a tremendous deal.\n\nBrace yourself for great changes, {name}.  We are now officially part of the Horde.", objectives = "Return to Silvermoon City and report back to Lor'themar Theron.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9628] = { id = 9628, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Salvaging the Data", description = "It's too late to assist the cartographers in completing their mission, but it appears they collected the data Harbinger Mikolaas was expecting. The crystal storing their survey information was not among their ransacked packs, so it must be in the hands of the Wrathscale naga.\n\nYou know that Harbinger Mikolaas will be saddened by the loss of the survey crew, but would want to salvage the survey data.", progress = "Were you able to find out what was keeping the survey team from returning?", completion = "<You tell Harbinger Mikolaas of the survey team's fate. He accepts the crystal from you, but remains silent for a long moment.>\n\nThey were good men, {name}, and they knew their mission would be dangerous. I'm grateful for your help in locating the team and recovering the crystal.\n\n\n\nWe've lost too many good men already, and our mission has only just begun.", objectives = "Obtain the Survey Data Crystal from the Wrathscale near the dead cartographers and return it to Harbinger Mikolaas at Blood Watch.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9629] = { id = 9629, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Catch and Release", description = "The Blacksilt murlocs on the southwestern coast are curious creatures. In some ways, they act barely sentient, yet in others, they show a remarkable degree of organization.\n\nI have a few theories about that, but no real way to test them until recently. I've devised a method that will allow me to track the murlocs I'm interested in without doing any lasting harm or interfering with their natural behavior. If you're willing to help with the marking, I'll gladly pay you for your assistance.", progress = "Did the device work? Have you marked the murlocs for my research?", completion = "Well done, {name}. I was worried that the marking device might malfunction, but it seems like everything went according to plan.", objectives = "Morae at Blood Watch wants you to 'mark' 6 Blacksilt Scouts using the Murloc Tagger.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9630] = { id = 9630, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Medivh's Journal", description = "Your name is getting around, {name}.  You've made your way into and out of Karazhan - more than most mortals can claim.\n\nI need to ask a special favor of you.  As part of our research, the Violet Eye has been trying to track down Medivh's own journal.\n\nUnfortunately, none of the agents we've sent inside have come out.  Wravien was the last to be sent; see if you can find him and see about any leads on the journal.", completion = "A vast wealth of information... I could spend years here!  I'm sure Dalaran will understand...", objectives = "Archmage Alturus at Deadwind Pass wants you to go into Karazhan and speak to Wravien.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9631] = { id = 9631, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Colleague's Aid", description = "There is a small detail I've forgotten to take into account.  The residue of Medivh's essence contained in this bone fragment is completely devoid of life - just like Arcanagos.\n\nThere is a way, however.  And I know just the person to help us.\n\nTravel to Area 52 in Netherstorm and show the bone fragment to Kalynna Lathred.  She will know just what to do.", progress = "Alturus sent you.  The stars spoke of your arrival.", completion = "Alturus wants to raise a whole dragon back from the dead?  Not an easy task by any stretch of the imagination.\n\nLet us discuss how we can be of mutual assistance, {name}.", objectives = "Take the Charred Bone Fragment to Kalynna Lathred at Area 52 in Netherstorm.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9632] = { id = 9632, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Newfound Allies", description = "Harbinger Mikolaas has done a commendable job of safeguarding Blood Watch, {class}, but our enemies are many and our resources few.\n\nOur weakness is well known to our enemies, but your contact with the forces of the Alliance is something they haven't accounted for. I have prepared a letter of introduction to the people of Auberdine, the closest Alliance settlement, proposing cooperation in the fight against our foes. Take it with you and seek out Huntress Kella Nightbow near the docks west of the Exodar.", progress = "Greetings, {class}. What have you there?", completion = "I can help you get to Auberdine. Fortunately, it's only a short boat trip away!", objectives = "Take the Letter of Introduction to Huntress Kella Nightbow in Azuremyst Isle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9633] = { id = 9633, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Way to Auberdine", description = "If you wait out on the dock, you'll see the boat arriving from the port of Auberdine in Darkshore. Once it has offloaded its passengers, you'll be able to board.\n\nAfter a short journey, the boat will put in at Auberdine and you'll be able to deliver your message.\n\nIt's probably best to take this to Thundris Windweaver, an old friend of mine and a well-respected citizen of the town.", progress = "Welcome to Auberdine, friend. What brings you to Darkshore?", completion = "<Thundris accepts the letter from you and reads it quickly, nodding.>\n\nThe isles the {race} call Azuremyst and Bloodmyst were inhabited long ago by my people. Some of the threats faced by Anchorite Paetheus and his brethren are ancient enemies of the night elves.\n\nI am certain that the people of Auberdine are willing to provide what aid we can to our new allies. As soon as I have spoken with the townspeople and the sentinels, I will send word to Paetheus.", objectives = "Take the boat from the dock near Huntress Kella Nightbow to Auberdine. Once you have arrived in Auberdine, take the Letter of Introduction to Thundris Windweaver.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9634] = { id = 9634, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alien Predators", description = "One thing we've learned in our travels is that extreme care must be taken when introducing wildlife from one world to another. When the Exodar crashed, it was carrying specimens of various Outland species, including an insectoid predator called the ravager.\n\nSome of the specimens were lost, but many others survived and took to the wild. If we don't keep them in check, they will upset the natural balance here on the islands.\n\nYou'll find these ravagers to the west of Kessel's Crossing, near the coast.", completion = "Well done, {name}. The ravager population will bear watching for some time to come, but we've made a good start.", objectives = "Kill 10 Bloodmyst Hatchlings then return to Vorkhan the Elekk Herder at Kessel's Crossing on Bloodmyst Isle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9635] = { id = 9635, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Zapthrottle Mote Extractor!", description = "The swamp gas is truly amazing, and can be very useful, mon!  But first, you gotta be able to suck it up, and that, my friend, requires a Zapthrottle Mote Extractor.\n\nNow, I could just give you the schematics, but I'll need something in return first.  How about some spare parts?  Last time I checked, there were plenty lying around near the broken steam pump at the Dead Mire, far to the northeast.\n\nI heard that the withered giants spread the pieces all over that dried-out lake bed.", progress = "You got those parts yet?  I've got some diving to do.", completion = "Alright!  Now if we only had a stretchy loop, a parchment clamp, a guzzle tube and some sticky duck ribbon.  Then we could really make something!\n\nOk, ok, I guess you've earned this, {name}.  Have fun!", objectives = "Bring 15 Steam Pump Parts to Mack Diver at Zabra'jin in Zangarmarsh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9636] = { id = 9636, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Zapthrottle Mote Extractor!", description = "Have you seen the swamp gas?  Isn't it just shiny?\n\nIt takes a Zapthrottle Mote Extractor to suck 'em dry though.  I could give you the plans to make one, but I really need some spare parts to fix stuff 'round here.\n\nLast time I checked, there were plenty of parts lying around near the steam pump at the Dead Mire to the northeast.  I think the withered giants broke the pump out there.\n\nShall we help each other out?", progress = "You got those parts yet?  I've got a compression coil to fix before Anchorite Ahuurn starts breathing down my neck!", completion = "Shiny!  And really, what engineer ever has enough spare parts just hanging around?  Ooh, maybe I could sell off the extra and buy me some of that Tigule and Foror's Strawberry Ice Cream?!  I just love strawberries!  Do you think they have any around here?\n\nOk, ok, I guess you've earned this, {name}.  Have fun!", objectives = "Bring 15 Steam Pump Parts to K. Lee Smallfry at Telredor in Zangarmarsh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9637] = { id = 9637, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kalynna's Request", description = "I left the Kirin Tor in pursuit of knowledge forbidden by those of my order; it is beyond ironic that I am now asked to assist them with that very same knowledge.\n\nIf I'm to perform this favor for you, you will have to do something for me first.  I want you to obtain two of the tomes I've been searching for.\n\nThe first one is called the Tome of Dusk and is owned by the orc warlock known as Nethekurse.  The second, known as the Book of Forgotten Names, belongs to the arakkoa known as Darkweaver Syth.", progress = "Have you obtained the tomes I seek, {name}?", completion = "Excellent, {name}.  I've been trying to obtain these books for a very long time.  It is fortunate that we were able to be of mutual assistance.", objectives = "Kalynna Lathred wants you to retrieve the Tome of Dusk from Grand Warlock Nethekurse in the Shattered Halls of Hellfire Citadel and the Book of Forgotten Names from Darkweaver Syth in the Sethekk Halls in Auchindoun.\n\nThis quest must be completed in Heroic difficulty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9638] = { id = 9638, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Good Hands", description = "Was I supposed to be looking for this journal?  It can't be... I don't quite recall...\n\nOf course!  It is Gradav you're thinking of.  He was looking for the book when I got here.  Surely he must've found it by now; why don't you go ask him about it?\n\nI'd lend you a hand... but these books are just so... interesting!", completion = "Can't you see I'm in the middle of something here?  What do you want?", objectives = "Speak to Gradav at the Guardian's Library in Karazhan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9639] = { id = 9639, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kamsis", description = "Journal, what journal?  You're thinking of Kamsis, surely.\n\nGo and ask her about it.  I can't leave my project right now or all my work will be wasted!", completion = "The journal you speak of... I was sent here to look for it wasn't I?", objectives = "Speak to Kamsis at the Guardian's Library in Karazhan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9640] = { id = 9640, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Shade of Aran", description = "Let me think for a second.  The Violet Eye... Medivh's Journal...  Why yes, it's all coming back to me now.\n\nI believe I had the journal you're looking for before I started to read these scrolls...\n\nAran... yes, Aran asked me for the book.  So nicely too.  I just had to give it to him.  He's Medivh's father after all, did you know?", progress = "Weren't you looking for a journal or something?", completion = "Did you find what you were looking for?  You were looking for something, weren't you?", objectives = "Obtain Medivh's Journal and return to Kamsis at the Guardian's Library in Karazhan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9641] = { id = 9641, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Irradiated Crystal Shards", description = "The Exodar's crash scattered pieces of fouled crystals all over Bloodmyst Isle, corrupting the water and the landscape.\n\nWe've even begun finding pieces of the crystals inside the flesh of animals taken for meat. I've uncovered a way to purify the shard and turn them into functional crystals, so if you bring me enough shards, I'll trade one of my completed crystals for them. So far I've found the shards in the bodies of bears, ravagers, flutterers, and treants inhabiting the corrupted part of the island.", progress = "Have you gathered crystal shards from the creatures of Bloodmyst?", completion = "Well done. These will provide the raw materials for another batch of enhancement crystals.\n\nYou're welcome to choose from among the three kinds of crystals I can make. I find each of them useful for stalking different kinds of prey.", objectives = "Vindicator Boros at Blood Watch wants you to bring him 10 Irradiated Crystal Shards.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9642] = { id = 9642, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Irradiated Crystal Shards", progress = "If you have more of the irradiated crystal shards, I'd be happy to exchange them for another of my crystals.", completion = "Very well, here are the crystals that I have, {name}. Use them well." }
quests[9643] = { id = 9643, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Constrictor Vines", description = "A good woodsman makes use of every available resource, {class}. Even the most bizarre creatures possess attributes we can use to our advantage.\n\nWith Blood Watch under constant assault from the Sunhawks, we're looking to a variety of natural defenses including traps. The lasher's thorny vines are perfectly suited to the construction of the traps I have in mind. The combination of sharp spines and deadly toxin will fell unwary attackers. Bring me the vines of mutated constrictors so that I can begin my work.", progress = "Did you manage to get the constrictor vines?", completion = "These seem sturdy enough to do the job. Thank you for your help, {name}. Your contribution to Blood Watch's defense will not be forgotten.", objectives = "Tracker Lyceon at Blood Watch wants you to bring him 6 Thorny Constrictor Vines.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9644] = { id = 9644, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nightbane", description = "You fulfilled your end of the deal.  I will now bind your essence to that of the dead blue dragon.\n\nThere is an urn in the Master's Terrace, should you touch that urn, you'll now release its energy and bring life back to the charred remains of Arcanagos.  Defeat the creature and retrieve its essence immediately!  You will need to take it to Alturus.\n\nShould you fail, the stars predict you will have let a great terror loose upon the skies.\n\nA terror known as Nightbane!", progress = "What news do you bring, {name}?", completion = "This is astounding!  Not only have you brought back Medivh's Journal, but you've also retrieved a fragment of his very essence.\n\nAs faint as this lingering essence is, it will reveal to us vital information about Medivh.  We will not forget this, {class}.", objectives = "Go to the Master's Terrace in Karazhan and touch the Blackened Urn to summon Nightbane. Retrieve the Faint Arcane Essence from Nightbane's corpse and bring it to Archmage Alturus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9645] = { id = 9645, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Master's Terrace", description = "Journal?  What journal?\n\nOh, right.  That journal!  The Violet Eye sent me here for it.  It's all coming back now.\n\n<Kamsis points to a page in the journal.>\n\nThis is the page that Alturus is interested in.  Did you know that while other people's journals serve as a record of their memories, Medivh's is literally just that?\n\nTry it.  Go to the Master's Terrace and read the page; you'll see just what I mean.  Might as well report to Alturus while you're at it.  I'm afraid I'll be here for a while.", progress = "You've returned!  What news do you bring?", completion = "It is a shame that the agents we sent succumbed to Karazhan's magic.  At least you managed to obtain what they were after.", objectives = "Go to the Master's Terrace in Karazhan and read Medivh's Journal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9646] = { id = 9646, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: Deathclaw", description = "By order of Harbinger Mikolaas: A bounty to be paid to the brave soul who returns with proof of the marauding bear Deathclaw's demise.\n\nDeathclaw should be considered extremely dangerous and is responsible for the killing of a survey team on the coast to the northwest of Blood Watch. Travelers are advised to avoid the area.", progress = "How can I help you, {class}?", completion = "Well done. From what I've heard, it couldn't have been an easy fight. You've more than earned your reward, {name}.", objectives = "Bring Deathclaw's Paw to Harbinger Mikolaas in Blood Watch.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9647] = { id = 9647, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Culling the Flutterers", description = "When we first encountered flutterers, they showed few signs of mutation. As the corruption got progressively worse, the moths and other species began to show signs of contamination.\n\nIt has progressed to the point where they damage nearly everything they come in contact with. They're amplifying the damage being done by the crystal shards scattered by the Exodar's crash. We have no choice but to begin culling their population in the lands north of Blood Watch.", completion = "In time, we'll have to devise a plan for returning the species to its native state, but for now, periodically culling their numbers is about the best we can hope for. Thank you for your help, {name}.", objectives = "Tracker Lyceon at Blood Watch wants you to kill 10 Royal Blue Flutterers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9648] = { id = 9648, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Maatparm Mushroom Menagerie", description = "Did you know mushroom hunting is far more dangerous than mushroom consumption? Mushroom hunters expose themselves to many unknowns - not including potential wildlife dangers!\n\nWhat would life be without a little danger? I am in need of mushrooms for my collection. Scattered throughout these unexplored wilds you will find four different types: An aquatic stinkhorn, a blood mushroom, a ruinous polyspore, and a fel cone fungus. They are each unique to various regions in Bloodmyst. Bring them to me.", progress = "Remember, the mushrooms I requested are each unique to the different environments of Bloodmyst.", completion = "Well, I did warn you - did I not? Hopefully this payment more than makes up for the mild discomfort that you may have suffered. Return to me when you have gained strength and perhaps I will have another job for you - mushrooms of course!", objectives = "Maatparm at Blood Watch wants 1 Aquatic Stinkhorn, 1 Blood Mushroom, 1 Ruinous Polyspore, and 1 Fel Cone Fungus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9649] = { id = 9649, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ysera's Tears", description = "Good to see you again, {name}! You were exceptionally efficient in completing the last task that I offered you. Perhaps you would be interested in another?\n\nTo the northeast lies Wyrmscar Island, home to a rare species of mushroom known as Ysera's tear - named after the green dragonlings that inhabit the island. I only require a small sampling of the mushroom, but I must warn you that the denizens of the island do not welcome visitors. Tread carefully.", progress = "Back so soon?", completion = "I hope this wasn't too strenuous a task, {name}. Once again you have proven yourself a competent and considerate {race}. I offer my gratitude and a small bit of monetary compensation.", objectives = "Maatparm at Blood Watch wants 2 Ysera's Tears.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9663] = { id = 9663, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Kessel Run", description = "You're just in time, {name}. Blood elf activity in this area has doubled in the past week. Our agents have informed us that the blood elves that call themselves Sunhawks plan to launch an offensive upon Azuremyst soon. I need you to get a warning out to our allies and compatriots.\n\nWarn High Chief Stillpine at Stillpine Hold, Exarch Menelaous at Azure Watch and Admiral Odesyus at Odesyus' Landing.\n\nTime is of the essence so I am lending you my elekk. Be sure to keep it out of water.", progress = "This is no time to relax!", completion = "Well done, {name}. This was a difficult test of your abilities, but you have passed with flying colors. To become a soldier of the Hand of Argus, you must pass many such tests.", objectives = "Kessel at Kessel's Crossing wants you to warn High Chief Stillpine at Stillpine Hold, Exarch Menelaous at Azure Watch and Admiral Odesyus at Odesyus' Landing of the imminent blood elf invasion. Return to Kessel when you complete this task. You have 15 minutes. (Be sure to keep it out of water.)", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9664] = { id = 9664, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Establishing New Outposts", description = "Welcome to the Plaguelands, {name}. As you know, the Forsaken and their allies hold the lands to the west of here against our best efforts. The Alliance commanders have decided that here in the east, we will establish new fortifications to tighten the noose around our enemies.\n\nTowers long abandoned since the days of Lordaeron are to be seized and rebuilt for this purpose. These lands are dangerous, and we could use your help.", completion = "Very good, {name}. It will be important for us to hold these towers against future attacks, and for that we may need your assistance until reinforcements can be brought in to secure the area.", objectives = "Capture Crown Guard Tower, Eastwall Tower, Northpass Tower and Plaguewood Tower in the Eastern Plaguelands, then return to Emmisary Whitebeard at Light's Hope Chapel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9665] = { id = 9665, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bolstering Our Defenses", description = "Agents of the Forsaken uncovered an Alliance plot to establish new bases here in the Eastern Plaguelands, at abandoned towers throughout the area.\n\nIt is imperative that we not allow them to establish a significant presence on our eastern borders, and so we must stave off this Alliance incursion. Our current plans are to drive them out of any towers they may have already seized, and occupy those that we have under our control against further attacks.", completion = "This is good news, {name}. It will be a constant struggle here in the Plaguelands until we have fully driven back the forces of the Alliance.\n\nUntil that day, I hope that we will have your continued assistance.", objectives = "Capture Crown Guard Tower, Eastwall Tower, Northpass Tower and Plaguewood Tower in the Eastern Plaguelands, then return to Emmisary Gormok at Light's Hope Chapel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9666] = { id = 9666, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Declaration of Power", description = "Have you seen the serpent men? The ones that call themselves naga?\n\n<Kessel spits.>\n\nThey dared make an advance upon this camp under cover of darkness only three nights ago. Can you believe the audacity of those primitive beasts?\n\nI need you to deliver a message to their leadership, {name}. To the northeast is Wrathscale Lair, home to Lord Xiz. Find him, slay him where he stands and drive this banner through his corpse.\n\nLet them know fear whenever they should see our standard!", progress = "Is it done?", completion = "I am sorry that you had to do that, {name}. Heavy-handed violence is not the draenei way, but sometimes it is the only way.\n\nThis is one of life's truths that many do not understand until it is too late. So it was for our people, when we were slaughtered at the hands of the orcs.\n\nBecoming a Hand of Argus is a process of rebirth. And with birth comes pain...", objectives = "Kessel at Kessel's Crossing on Bloodmyst Isle wants you to kill Lord Xiz at Wrathscale Lair and drive the Draenei Banner through his dead body.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9667] = { id = 9667, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Saving Princess Stillpine", description = "Help me, {name}! The Bristlelimb captured me and are planning to sacrifice me to their foul gods!\n\nHigh Chief Bristlelimb holds the key that opens the cage. To force him to appear, you must slaughter the evil Bristlelimb furbolgs that inhabit the enclave, just two camps to the west of this camp. If you kill enough of them, he will surely come for vengeance! When he shows up, kill him and get the key!\n\nMy father will richly reward you if you can save me!", completion = "Once again you have proven yourself to be all that was prophesied. You have the eternal gratitude of the high chief {name} -- and these Stillpine relics to choose from...", objectives = "Release Princess Stillpine from her cage and then speak with Stillpine Ambassador Frasaboo at Blood Watch.\n\nYou must kill High Chief Bristlelimb for the key that opens the cage.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9668] = { id = 9668, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Report to Exarch Admetius", description = "A Hand of Argus soldier is many things: Obedient, brave, intelligent, and above all, honorable. You may yet exhibit some of these traits, {class}.\n\nReport to Exarch Admetius at Blood Watch if you are still interested in joining the Hand. He and his subordinates will further train you in the ways of the draenei soldier.\n\nAnd remember this, {name}: Honorable people do not always perform honorably. Sometimes they cannot.\n\nYou will find Blood Watch just up this road, to the north.", completion = "I had a feeling that you would make it this far, {class}. If you are willing to go further, I am willing to teach you...", objectives = "Speak with Exarch Admetius at Blood Watch.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9669] = { id = 9669, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Missing Expedition", description = "About a week ago, my research team and I were out exploring the western wilds of Bloodmyst when we were attacked by bloodthirsty spiders. The effect of the crystal contamination was clearly evident as these spiders were massive and extremely aggressive.\n\nI managed to escape but my team wasn't so lucky. We must not let the same fate befall others. Go west to the Amberweb Pass and destroy the spiders and their matriarch, Zarakh.", completion = "Incredible! Did you find any survivors?\n\n<Achelus lowers his voice to a whisper.>\n\nI'll be honest, {name}; nobody else was willing to take on this mission. You are a brave {class}...", objectives = "Kill 8 Myst Spinners, 8 Myst Leechers and their leader, Zarakh. Return to Achelus at Blood Watch when the task is complete.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9670] = { id = 9670, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "They're Alive! Maybe...", description = "It was a bloody mess, {name}. We were ambushed by a large pack of these spiders. Their progenitor descended upon us with incredible speed and wrapped us up in cocoons.\n\nAfter we were webbed, she began to lay eggs near us. We were to be food for her young! FOOD!\n\nI managed to cut my way out and escape but I will not leave the others behind. So far I've been unsuccessful in nearing the pass. Would you lend a hand?\n\nDestroy those cocoons! Hopefully some of our team is still alive!", progress = "Any luck?", completion = "You rescued over half the team! Word of your deed will definitely get back to Blood Watch and the exarch. Thanks again, {name}.", objectives = "Researcher Cornelius has asked that you free 5 Expedition Researchers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9671] = { id = 9671, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Urgent Delivery", objectives = "Are you {name}? It's about time! I'd just about given up on finding you!\n\nThere's an urgent message waiting for you at the mailbox. The person that gave it to me was a human admiral from Azuremyst. Admiral Odesy-something... the name escapes me. He said you would know who he was.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9672] = { id = 9672, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Bloodcurse Legacy", description = "Dear friend,\n\nMy hand trembles as I ink this letter. I pray that it reaches you in time.\n\nLast night, Edward Hanes, captain of the ship 'Lost Hope', appeared before me in my tent. The same Edward Hanes that died of scurvy 20 years ago.\n\nThis apparition told me a tale that made my heart tremble. A tale that I need you to hear and a mission that I need you to accomplish. Will you do it? Will you seek out Edward on Wyrmscar Island, northeast of your base?\n\nRegards,\n\nAdmiral Odesyus", completion = "Have you heard of the bloodcurse, landlubber? No, of course you haven't. The bloodcurse is what sunk all these ships. The spoiled, desecrated part of the water here is known as Bloodcursed Reef - a part of the world you never want to visit. I've been here myself for 20 years.\n\nScurvy my foot! I died on these wild shores as food for the dragons... Ah, but that's another story for another time. Right now, we have to help the poor souls that are trapped in that reef.", objectives = "Admiral Odesyus has asked that you find and speak with Captain Edward Hanes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9673] = { id = 9673, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beast Training", description = "Beyond bonding with your chosen pet, there remains the intricacies of caring and training it.  For this, Halthenis the beast trainer of Silvermoon City can show you the way.\n\nHe always shows the utmost respect for my students, if they do the same for him.  Do not disappoint me.", sourceObjective = "Speak with Halthenis in Silvermoon City.Beyond bonding with your chosen pet, there remains the intricacies of caring and training it. For this, Halthenis the beast trainer of Silvermoon City can show you the way.\n\nHe always shows the utmost respect for my students, if they do the same for him. Do not disappoint me.", sourceObjectiveStatus = "unverified-source-field" }
quests[9674] = { id = 9674, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Bloodcursed Naga", description = "They say when the world was sundered, this land cried the loudest. It was here that thousands of night elves faded into oblivion and in their place rose terrible creatures of hate - the naga.\n\nObedient to their twisted queen, Azshara, they would destroy all that would dare pass through their sea. It would remain this way for thousands of years - until now.\n\nThe first order of business is to remove the bloodcursed naga from the reef.", progress = "They're nasty creatures...", completion = "A good start, but there's much more to be done!", objectives = "Captain Edward Hanes on Wyrmscar Island wants you to kill 10 Bloodcursed Naga.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9675] = { id = 9675, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beast Training", description = "Oh, one more thing!  You'll want to speak with Ganaar at the Exodar.  He'll be able to teach you the last bits of knowledge necessary to care for your pet and train it.\n\nYou can find him in the southwest corner of the Traders Tier.", sourceObjective = "Speak with Ganaar at the Traders Tier of the Exodar.Oh, one more thing!  You'll want to speak with Ganaar at the Exodar. He'll be able to teach you the last bits of knowledge necessary to care for your pet and train it.\n\nYou can find him in the southwest corner of the Traders Tier.", sourceObjectiveStatus = "unverified-source-field" }
quests[9676] = { id = 9676, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Paladin Training", description = "As you advance within your class, you will want to take advantage of the training that your class trainer can provide you.  For young paladins here on Sunstrider Isle, your trainer is Jesthenis Sunstriker. Speak with Jesthenis and see what training he has available for you.  The things he will teach do have a cost, so bring some coin with you.\n\nYour trainer - as with all the trainers on Sunstrider Isle - is inside the Sunspire on the lower level.", completion = "I see the pride swelling in your chest. Already you fancy yourself one of the Blood Knights.\n\nIn time, you will earn your place among us. But first you must learn to harness and master the powers of the Light, hone your skills at arms, and prove your worthiness.\n\nYou must be prepared to endure the derision, fear, and revulsion of those you're sworn to defend. So it is among those who can't comprehend the price of the great power that safeguards them. Keep your head high and your blade at the ready, {name}.", objectives = "Speak with Jesthenis Sunstriker - the Paladin class trainer - inside the Sunspire on Sunstrider Isle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9677] = { id = 9677, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Summons from Knight-Lord Bloodvalor", description = "{name}, you have excelled in your early training and distinguished yourself among those who would become Blood Knights. You are ready to undertake the next phase of your training and, to that end, Knight-Lord Bloodvalor himself has asked to speak with you.\n\nI have no doubt that Knight-Lord Bloodvalor wishes to set a trial for you to test your abilities and training. You will find him in the Blood Knight headquarters in Silvermoon City's Farstriders' Square. I wish you well, {name}.", sourceObjective = "Speak with Knight-Lord Bloodvalor in Farstriders' Square in Silvermoon City.", sourceObjectiveStatus = "unverified-source-field" }
quests[9678] = { id = 9678, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The First Trial", description = "You have learned much of combat and bloodshed, initiate, but there is much more to our order.\n\nMastery of the Light requires a focused mind and tremendous willpower. Without these, you are little better than a street thug.\n\nThere is an island in the northeastern reaches of the Ghostlands, called the Isle of Tribulations, that we use to hone these skills. You will find a brazier within a shallow cave there. Kneel before the brazier, light it, and focus on what you see before your eyes.", objectives = "Travel to the island Knight-Lord Bloodvalor described, find the cave, and light the brazier. When the First Trial is over, return to Knight-Lord Bloodvalor in Silvermoon City.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9680] = { id = 9680, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Digging Up the Past", description = "Kamsis was right!  This information is extremely important.\n\nIf Medivh weaved his own essence into the magic he used to defeat the dragon, it is quite possible we could retrieve even a faint residue of that essence from the dragon's remains.  What great insight may lie beneath the ashes of Deadwind Pass, awaiting discovery.\n\nGo to the mountains south of Karazhan and bring me back a bone fragment of seemingly draconic origin.", progress = "Have you retrieved the bone fragment I require, {name}?", completion = "Excellent!  Though small in size, this fragment is teeming with energy, I can feel it!", objectives = "Archmage Alturus wants you to go to the mountains south of Karazhan in Deadwind Pass and retrieve a Charred Bone Fragment.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9681] = { id = 9681, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Study in Power", description = "Do not think me unduly harsh, {name}. Stillblade knew well what he was being sent to do. He understood and accepted his duty and is an example for all aspiring Blood Knights.\n\nMy words are no eulogy, {name}. Stillblade's service to us is far from over and you will be the instrument of his resurrection.\n\nYour education in the order's ways has just begun. With the betrayal of Kael'thas and the loss of our power source, you must learn new methods of wielding the Light. Seek out Magister Astalor Bloodsworn.", sourceObjective = "Speak with Magister Astalor Bloodsworn in the hidden chamber beneath Blood Knight headquarters.", sourceObjectiveStatus = "unverified-source-field" }
quests[9682] = { id = 9682, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hopeless Ones...", description = "On a ledge of the reef, deeper than where you found the bloodcursed naga, you will find the hopeless ones: The bloodcursed voyagers, ghosts of those taken by the bloodcurse.\n\nIt is regrettable, what I ask of you now... but they must be destroyed and their cursed shells brought back to me.\n\nTheir souls must be put to rest. Return to me when you have done as asked and I shall give you one final task.", progress = "Do not mourn their demise, {name}.", completion = "You have done the hopeless ones a great service, {name}. There is but one final task: Destroy the leader of the Bloodcursed.", objectives = "Captain Edward Hanes on Wyrmscar Island wants you to recover 4 Bloodcursed Souls.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9683] = { id = 9683, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ending the Bloodcurse", description = "To the south you will find Bloodcurse Isle. Atop the island you will find a shrine dedicated to the beloved queen of the naga, Azshara. Destroy the statue - burn it in effigy! This will surely draw the ire of Atoph, the Bloodcursed leader.\n\nSlay Atoph and return to me!", progress = "Atoph must be lured out!", completion = "You did it! Hundreds of souls are grateful for all that you have done.\n\nAllow me to make an offering...", objectives = "Captain Edward Hanes on Wyrmscar Island wants you to destroy the Statue of Queen Azshara and kill Atoph the Bloodcursed.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9684] = { id = 9684, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Claiming the Light", description = "Take this vessel, {name}. The enchantment it bears will allow you to draw the last vestiges of the Light surrounding these magisters. They once tended the captive naaru and some of its energy yet remains within them.\n\nIt will be just enough to restore your comrade to life.\n\nDo not worry about the magisters, {name}. I have seen to their care, and Lord Solanar assures me that Lady Liadrin seeks a new source of power even now.", objectives = "Use the Shimmering Vessel on the Blood Elf Magisters to fill it and return to Knight-Lord Bloodvalor in Silvermoon City.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9685] = { id = 9685, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Redeeming the Dead", description = "While you were preparing the vessel, I sent a group of initiates to retrieve Sangrias Stillblade. You will find him on the top level of Silvermoon's inn with an attendant. Make your way there with all haste and unleash the vessel's magic to restore him to life.\n\nTime is of the essence, {name}. Once he has been dead for too long, not even the Light can bring him back to us. Return to me once you have resurrected Stillblade.You will learn:", objectives = "Take the Filled Shimmering Vessel to Silvermoon City's inn and use its magic to resurrect Sangrias Stillblade.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9686] = { id = 9686, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Second Trial", description = "You stand on the verge of adept status in the order, {name}. First, you must prove your worthiness by undertaking another trial.\n\nThe Second Trial differs from the first in that there will be no surprises this time. The challenge before you is simple; you must face and best four Blood Knight champions in combat.\n\nWhen you accept the challenge, a crystal will appear in the middle of the pavilion. Touch it to begin your trial and do not stray far from the building.\n\nAre you prepared?", objectives = "Complete the Second Trial by defeating Champion Bloodwrath, Champion Lightrend, Champion Swiftblade, and Champion Sunstriker in the pavilion near Master Kelerun Bloodmourn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9687] = { id = 9687, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Restoring Sanctity", description = "Not long ago, the once tranquil owlkin of the region appeared on the shores of this island. One by one they would come to steal the bones of the fallen dragons. I do not know what would cause these creatures such distress or why they would want the bones of the deceased, but the spirits of the brood have grown restless due to this sacrilege.\n\nTo the west, across the Crimson Reach, you will find Ragefeather Ridge. Venture to the owlkin encampments and recover the pilfered dragon bones.", progress = "The dragon wars have long since passed. All that remains are bones and the agitated remnants of Ysera's brood.", completion = "A ritual? The owlkin had lived in harmony with the land for thousands of years. Such a thing is an aberration!\n\nSuch a pity...", objectives = "Prince Toreth on Wyrmscar Island wants you to recover 8 Dragon Bones.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
